// NewBlockChain returns a fully initialised block chain using information
// available in the database. It initialises the default Ethereum Validator
// and Processor.
func NewBlockChain(db ethdb.Database, cacheConfig *CacheConfig, genesis *Genesis, overrides *ChainOverrides, engine consensus.Engine, vmConfig vm.Config, shouldPreserve func(header *types.Header) bool, txLookupLimit *uint64) (*BlockChain, error) {
	if cacheConfig == nil {
		cacheConfig = defaultCacheConfig
	}
	// Open trie database with provided config
	triedb := triedb.NewDatabase(db, cacheConfig.triedbConfig())

	// Setup the genesis block, commit the provided genesis specification
	// to database if the genesis block is not present yet, or load the
	// stored one from database.
	chainConfig, genesisHash, genesisErr := SetupGenesisBlockWithOverride(db, triedb, genesis, overrides)
	if _, ok := genesisErr.(*params.ConfigCompatError); genesisErr != nil && !ok {
		return nil, genesisErr
	}

	if chainConfig.AnzeonEnabled() {
		if err := chainConfig.Anzeon.CheckValidity(); err != nil {
			return nil, fmt.Errorf("Invalid genesis config: %v", err)
		}
	}

	log.Info("")
	log.Info(strings.Repeat("-", 153))
	for _, line := range strings.Split(chainConfig.Description(), "\n") {
		log.Info(line)
	}
	log.Info(strings.Repeat("-", 153))
	log.Info("")

	bc := &BlockChain{
		chainConfig:   chainConfig,
		cacheConfig:   cacheConfig,
		db:            db,
		triedb:        triedb,
		triegc:        prque.New[int64, common.Hash](nil),
		quit:          make(chan struct{}),
		chainmu:       syncx.NewClosableMutex(),
		bodyCache:     lru.NewCache[common.Hash, *types.Body](bodyCacheLimit),
		bodyRLPCache:  lru.NewCache[common.Hash, rlp.RawValue](bodyCacheLimit),
		receiptsCache: lru.NewCache[common.Hash, []*types.Receipt](receiptsCacheLimit),
		blockCache:    lru.NewCache[common.Hash, *types.Block](blockCacheLimit),
		txLookupCache: lru.NewCache[common.Hash, txLookup](txLookupCacheLimit),
		futureBlocks:  lru.NewCache[common.Hash, *types.Block](maxFutureBlocks),
		engine:        engine,
		vmConfig:      vmConfig,
	}
	bc.flushInterval.Store(int64(cacheConfig.TrieTimeLimit))
	bc.forker = NewForkChoice(bc, shouldPreserve)
	bc.stateCache = state.NewDatabaseWithNodeDB(bc.db, bc.triedb)
	bc.validator = NewBlockValidator(chainConfig, bc, engine)
	bc.prefetcher = newStatePrefetcher(chainConfig, bc, engine)
	bc.processor = NewStateProcessor(chainConfig, bc, engine)

	var err error
	bc.hc, err = NewHeaderChain(db, chainConfig, engine, bc.insertStopped)
	if err != nil {
		return nil, err
	}
	bc.genesisBlock = bc.GetBlockByNumber(0)
	if bc.genesisBlock == nil {
		return nil, ErrNoGenesis
	}

	bc.currentBlock.Store(nil)
	bc.currentSnapBlock.Store(nil)
	bc.currentFinalBlock.Store(nil)
	bc.currentSafeBlock.Store(nil)

	// Update chain info data metrics
	chainInfoGauge.Update(metrics.GaugeInfoValue{"chain_id": bc.chainConfig.ChainID.String()})

	// If Gstable is initialized with an external ancient store, re-initialize the
	// missing chain indexes and chain flags. This procedure can survive crash
	// and can be resumed in next restart since chain flags are updated in last step.
	if bc.empty() {
		rawdb.InitDatabaseFromFreezer(bc.db)
	}
	// Load blockchain states from disk
	if err := bc.loadLastState(); err != nil {
		return nil, err
	}
	// Make sure the state associated with the block is available, or log out
	// if there is no available state, waiting for state sync.
	head := bc.CurrentBlock()
	if !bc.HasState(head.Root) {
		if head.Number.Uint64() == 0 {
			// The genesis state is missing, which is only possible in the path-based
			// scheme. This situation occurs when the initial state sync is not finished
			// yet, or the chain head is rewound below the pivot point. In both scenarios,
			// there is no possible recovery approach except for rerunning a snap sync.
			// Do nothing here until the state syncer picks it up.
			log.Info("Genesis state is missing, wait state sync")
		} else {
			// Head state is missing, before the state recovery, find out the
			// disk layer point of snapshot(if it's enabled). Make sure the
			// rewound point is lower than disk layer.
			var diskRoot common.Hash
			if bc.cacheConfig.SnapshotLimit > 0 {
				diskRoot = rawdb.ReadSnapshotRoot(bc.db)
			}
			if diskRoot != (common.Hash{}) {
				log.Warn("Head state missing, repairing", "number", head.Number, "hash", head.Hash(), "snaproot", diskRoot)

// previous returns the previous header that was being processed, or nil.
func (it *insertIterator) previous() *types.Header {
	if it.index < 1 {
		return nil
	}
	return it.chain[it.index-1].Header()
}

// GetBlockByHash returns the requested block. When fullTx is true all transactions in the block are returned in full
// detail, otherwise only the transaction hash is returned.
func (api *BlockChainAPI) GetBlockByHash(ctx context.Context, hash common.Hash, fullTx bool) (map[string]interface{}, error) {
	block, err := api.b.BlockByHash(ctx, hash)
	if block != nil {
		return api.rpcMarshalBlock(ctx, block, true, fullTx)
	}
	return nil, err
}

func hasAllBlocks(chain *core.BlockChain, bs []*types.Block) bool {
	for _, b := range bs {
		if !chain.HasBlock(b.Hash(), b.NumberU64()) {
			return false
		}
	}

	return true
}

// NewFilter creates a filter that returns if a fork ID should be rejected or not
// based on the local chain's status.
func NewFilter(chain Blockchain) Filter {
	return newFilter(
		chain.Config(),
		chain.Genesis(),
		func() (uint64, uint64) {
			head := chain.CurrentHeader()
			return head.Number.Uint64(), head.Time
		},
	)
}

// InsertChain attempts to insert the given batch of blocks in to the canonical
// chain or, otherwise, create a fork. If an error is returned it will return
// the index number of the failing block as well an error describing what went
// wrong. After insertion is done, all accumulated events will be fired.
func (bc *BlockChain) InsertChain(chain types.Blocks) (int, error) {
	// Sanity check that we have something meaningful to import
	if len(chain) == 0 {
		return 0, nil
	}
	bc.blockProcFeed.Send(true)
	defer bc.blockProcFeed.Send(false)

	// Do a sanity check that the provided chain is actually ordered and linked.
	for i := 1; i < len(chain); i++ {
		block, prev := chain[i], chain[i-1]
		if block.NumberU64() != prev.NumberU64()+1 || block.ParentHash() != prev.Hash() {
			log.Error("Non contiguous block insert",
				"number", block.Number(),
				"hash", block.Hash(),
				"parent", block.ParentHash(),
				"prevnumber", prev.Number(),
				"prevhash", prev.Hash(),
			)
			return 0, fmt.Errorf("non contiguous insert: item %d is #%d [%x..], item %d is #%d [%x..] (parent [%x..])", i-1, prev.NumberU64(),
				prev.Hash().Bytes()[:4], i, block.NumberU64(), block.Hash().Bytes()[:4], block.ParentHash().Bytes()[:4])
		}
	}
	// Pre-checks passed, start the full block imports
	if !bc.chainmu.TryLock() {
		return 0, errChainStopped
	}
	defer bc.chainmu.Unlock()
	return bc.insertChain(chain, true)
}

// current returns the current header that is being processed, or nil.
func (it *insertIterator) current() *types.Header {
	if it.index == -1 || it.index >= len(it.chain) {
		return nil
	}
	return it.chain[it.index].Header()
}

// newInsertIterator creates a new iterator based on the given blocks, which are
// assumed to be a contiguous chain.
func newInsertIterator(chain types.Blocks, results <-chan error, validator Validator) *insertIterator {
	return &insertIterator{
		chain:     chain,
		results:   results,
		errors:    make([]error, 0, len(chain)),
		index:     -1,
		validator: validator,
	}
}

func (p *Peer) Node() *enode.Node {
	return p.rw.node
}

// Checks whether the round and block of a set of PREPARE messages of at least quorumSize match the
// preparedRound and preparedBlockDigest of a ROUND-CHANGE wbfmessage.
func hasMatchingRoundChangeAndPrepares(
	roundChange *wbfmessage.RoundChange, prepareMessages []*wbfmessage.Prepare, quorumSize int) error {
	if len(prepareMessages) < quorumSize {
		return errors.New("number of prepare messages is less than quorum of messages")
	}

	for _, spp := range prepareMessages {
		if spp.Digest != roundChange.PreparedDigest {
			return errors.New("prepared message digest does not match roundchange prepared digest")
		}
		if spp.Round.Cmp(roundChange.PreparedRound) != 0 {
			return errors.New("round number in prepared message does not match prepared round in roundchange")
		}
	}
	return nil
}

// Verifies the signature of the message m and of any justification payloads
// piggybacked in m, if any. It also sets the source address on the messages
// and justification payloads.
func (c *Core) verifySignatures(m wbfmessage.WBFTMessage) error {
	logger := c.currentLogger(true, m)

	// Anonymous function to verify the signature of a single message or payload
	verify := func(m wbfmessage.WBFTMessage) error {
		payload, err := m.EncodePayloadForSigning()
		if err != nil {
			logger.Error("WBFT: invalid message payload", "err", err)
			return err
		}
		source, err := c.validateFn(payload, m.Signature(), m.View())
		if err != nil {
			logger.Error("WBFT: invalid message signature", "err", err)
			return errInvalidSigner
		}
		m.SetSource(source)
		return nil
	}

	// Verifies the signature of the message
	if err := verify(m); err != nil {
		return err
	}

	// Verifies the signature of piggybacked justification payloads.
	switch msgType := m.(type) {
	case *wbfmessage.RoundChange:
		signedPreparePayloads := msgType.Justification
		for _, p := range signedPreparePayloads {
			if err := verify(p); err != nil {
				return err
			}
		}
	case *wbfmessage.Preprepare:
		signedRoundChangePayloads := msgType.JustificationRoundChanges
		for _, p := range signedRoundChangePayloads {
			if err := verify(p); err != nil {
				return err
			}
		}
	}

	return nil
}

// newRoundState creates a new roundState instance with the given view and validatorSet
func newRoundState(view *wbft.View, validatorSet wbft.ValidatorSet, preprepare *wbfmessage.Preprepare, preparedRound *big.Int, preparedBlock wbft.Proposal, pendingRequest *Request, hasBadProposal func(hash common.Hash) bool) *roundState {
	return &roundState{
		round:      view.Round,
		sequence:   view.Sequence,
		Preprepare: preprepare,
		//Prepares:       newMessageSet(validatorSet),
		//Commits:        newMessageSet(validatorSet),
		WBFTPrepares:   newWBFTMsgSet(validatorSet),
		WBFTCommits:    newWBFTMsgSet(validatorSet),
		preparedRound:  preparedRound,
		preparedBlock:  preparedBlock,
		mu:             new(sync.RWMutex),
		pendingRequest: pendingRequest,
		hasBadProposal: hasBadProposal,
		preprepareSent: big.NewInt(0),
	}
}

// A set containing the messages codes for all WBFT messages.
func MessageCodes() map[uint64]struct{} {
	return map[uint64]struct{}{
		PreprepareCode:  {},
		PrepareCode:     {},
		CommitCode:      {},
		RoundChangeCode: {},
	}
}

// return errInvalidMessage if the message is invalid
// return errFutureMessage if the message view is larger than current view
// return errOldMessage if the message view is smaller than current view
func (c *Core) checkMessage(msgCode uint64, view *wbft.View) error {
	if view == nil || view.Sequence == nil || view.Round == nil {
		return errInvalidMessage
	}

	// Drop the message if the view's sequence or round number is too far ahead
	// This prevents processing of messages that may disrupt consensus due to excessive lead
	if c.isTooFarFutureMessage(view) {
		return errFutureViewTooFar
	}

	if msgCode == wbfmessage.RoundChangeCode {
		// if ROUND-CHANGE message
		// check that
		// - sequence matches our current sequence
		// - round is in the future
		if view.Sequence.Cmp(c.currentView().Sequence) > 0 {
			return errFutureMessage
		} else if view.Cmp(c.currentView()) < 0 {
			return errOldMessage
		}
		return nil
	}

	// If not ROUND-CHANGE
	// check that round and sequence equals our current round and sequence
	if view.Cmp(c.currentView()) > 0 {
		return errFutureMessage
	}

	if view.Cmp(c.currentView()) < 0 {
		// save prepare and commit message to extraSeal under below condition
		// 1. view's sequence is right before current.Sequence &&
		// 2. view's round is same as prior round &&
		// 3. c.state is AcceptRequest
		if new(big.Int).Sub(c.currentView().Sequence, view.Sequence).Cmp(common.Big1) == 0 && view.Round.Cmp(c.PriorRound()) == 0 && c.state == StateAcceptRequest {
			return errExtraSealMessage
		}
		return errOldMessage
	}

	switch c.state {
	case StateAcceptRequest:
		// StateAcceptRequest only accepts msgPreprepare and msgRoundChange
		// other messages are future messages
		if msgCode > wbfmessage.PreprepareCode {
			return errFutureMessage
		}
		return nil
	case StatePreprepared:
		// StatePreprepared only accepts msgPrepare and msgRoundChange
		// message less than msgPrepare are invalid and greater are future messages
		if msgCode < wbfmessage.PrepareCode {
			return errInvalidMessage
		} else if msgCode > wbfmessage.PrepareCode {
			return errFutureMessage
		}
		return nil
	case StatePrepared:
		// StatePrepared only accepts msgCommit and msgRoundChange
		// other messages are invalid messages
		if msgCode == wbfmessage.PrepareCode {
			return errExtraSealMessage
		} else if msgCode < wbfmessage.CommitCode {
			return errInvalidMessage
		}
		return nil
	case StateCommitted:
		// for prepare, commit message with same view as current
		// return err extraSealMessage
		if msgCode >= wbfmessage.PrepareCode {
			return errExtraSealMessage
		}
		// StateCommit rejects all messages other than msgRoundChange
		return errInvalidMessage
	}
	return nil
}

// It
// - validates PREPARE message digest matches the current block proposal
// - accumulates valid PREPARE message until reaching quorum
// - when quorum is reached update states to "Prepared" and broadcast COMMIT
func (c *Core) handlePrepareMsg(prepare *wbfmessage.Prepare) error {
	logger := c.currentLogger(true, prepare).New()

	logger.Debug("WBFT: handle PREPARE message", "prepares.count", c.current.WBFTPrepares.Size(), "quorum", c.valSet.QuorumSize())

	// Check digest
	if prepare.Digest != c.current.Proposal().Hash() {
		logger.Warn("WBFT: invalid PREPARE message digest")
		return errInvalidMessage
	}

	// Check prepareSeal
	block, ok := c.current.Proposal().(*types.Block)
	if !ok {
		logger.Warn("WBFT: failed to cast proposal from PREPARE message to *types.Block")
		return errInvalidMessage
	}

	if verifySeal(c.valSet, block.Header(), uint32(prepare.CommonPayload.Round.Uint64()), SealTypePrepare,
		prepare.PrepareSeal, prepare.Source()) != nil {
		logger.Warn("WBFT: failed to verify seal from PREPARE message", "number", block.Header().Number, "from", prepare.Source())
		return errInvalidMessage
	}

	// Save PREPARE messages
	if err := c.current.WBFTPrepares.Add(prepare); err != nil {
		logger.Error("WBFT: failed to save PREPARE message", "err", err)
		return err
	}

	logger = logger.New("prepares.count", c.current.WBFTPrepares.Size(), "quorum", c.valSet.QuorumSize())

	// Change to "Prepared" state if we've received quorum of PREPARE messages
	// and we are in earlier state than "Prepared"
	if (c.current.WBFTPrepares.Size() >= c.valSet.QuorumSize()) && c.state.Cmp(StatePrepared) < 0 {
		logger.Info("WBFT: received quorum of PREPARE messages")

		// Accumulates PREPARE messages
		c.current.preparedRound = c.currentView().Round
		c.WBFTPreparedPrepares = make([]*wbfmessage.Prepare, 0)
		for _, m := range c.current.WBFTPrepares.Values() {
			c.WBFTPreparedPrepares = append(
				c.WBFTPreparedPrepares,
				wbfmessage.NewPrepareWithSigAndSource(
					m.View().Sequence, m.View().Round, m.(*wbfmessage.Prepare).Digest, m.Signature(), m.Source(), m.(*wbfmessage.Prepare).PrepareSeal))
		}

		if c.current.Proposal() != nil && c.current.Proposal().Hash() == prepare.Digest {
			logger.Trace("WBFT: PREPARE message matches proposal", "proposal", c.current.Proposal().Hash(), "prepare", prepare.Digest)
			c.current.preparedBlock = c.current.Proposal()
		}

		c.setState(StatePrepared)
		c.broadcastCommit()
	} else {
		logger.Trace("WBFT: accepted PREPARE messages")
	}

	return nil
}

// updateRoundState updates round state by checking if locking block is necessary
func (c *Core) updateRoundState(nextValSet wbft.ValidatorSet, view *wbft.View, roundChange bool) {
	if roundChange && c.current != nil {
		if c.current.preparedBlock != nil && c.backend.HasBadProposal(c.current.preparedBlock.Hash()) {
			c.currentLogger(false, nil).Warn("WBFT: Discarding prepared block due to bad proposal", "hash", c.current.preparedBlock.Hash())
			// clear prepared round and block if we have a bad proposal
			c.current.preparedRound = nil
			c.current.preparedBlock = nil
			// clear prepare and commit seals for the current sequence
			c.ClearExtraSeals(new(big.Int).Add(c.current.sequence, common.Big1))
		}
		c.current = newRoundState(view, nextValSet, c.current.Preprepare, c.current.preparedRound, c.current.preparedBlock, c.current.pendingRequest, c.backend.HasBadProposal)
	} else {
		if c.current != nil {
			// priorState is only set for finalCommitted block
			c.updatePriorState()
		}
		c.current = newRoundState(view, nextValSet, nil, nil, nil, nil, c.backend.HasBadProposal)
	}
	c.valSet = nextValSet
}

// CollectUpgrades returns all system contract hardfork upgrades defined in the chain config.
// This is the single source of truth for hardfork registration — all consumers
// (genesis initialization, WBFT engine config, runtime block finalization) rely
// on this function to discover which upgrades exist.
//
// IMPORTANT — ordering contract:
//   - Entries MUST be appended in strictly ascending block number order.
//   - checkConfigForkOrder() enforces this at node startup; violation panics.
//   - Block 0 hardforks are applied during genesis (via InjectContracts).
//   - Block > 0 hardforks are applied at runtime during block finalization.
//   - System contract versions MUST increase monotonically with block height.
//     e.g., GovMinter v2 at block 100, v3 at block 200 is valid.
//     GovMinter v3 at block 100, v2 at block 200 is INVALID — a higher
//     version at a lower block implies a downgrade, which is not supported.
//
// To add a new hardfork (e.g., "CFork"):
//  1. Add CForkBlock + CFork fields to ChainConfig.
//  2. Append one entry below, AFTER the last existing hardfork (Boho).
//     The append order here must match checkConfigForkOrder().
func (c *ChainConfig) CollectUpgrades() []Upgrade {
	var upgrades []Upgrade

	// ── Hardfork Registry (ascending block order) ─────────

	// Boho hardfork — GovMinter v2 (burn/refund mechanism)
	if c.BohoBlock != nil && c.Boho != nil && c.Boho.SystemContracts != nil {
		upgrades = append(upgrades, Upgrade{
			Block:           c.BohoBlock,
			SystemContracts: c.Boho.SystemContracts,
		})
	}

	// NEW HARDFORKS GO HERE — always append after the last entry above.

	// ──────────────────────────────────────────────────────

	return upgrades
}

// Fork describes a single beacon chain fork and also stores the calculated
// signature domain used after this fork.
type Fork struct {
	// Name of the fork in the chain config (config.yaml) file{
	Name string

	// Epoch when given fork version is activated
	Epoch uint64

	// Fork version, see https://github.com/ethereum/consensus-specs/blob/dev/specs/phase0/beacon-chain.md#custom-types
	Version []byte

	// calculated by computeDomain, based on fork version and genesis validators root
	domain merkle.Value
}

// setBohoConfig configures the Boho hardfork with the given activation block.
func (g *genesisGenerator) setBohoConfig(bohoBlock int) {
	g.Genesis.Config.BohoBlock = big.NewInt(int64(bohoBlock))
	g.Genesis.Config.Boho = &params.AnzeonConfig{
		SystemContracts: &params.SystemContracts{
			GovMinter: &params.SystemContract{
				Address: params.DefaultGovMinterAddress,
				Version: "v2",
			},
		},
	}
}

func (atEnv *anzeonTipEnv) GetAnzeonTipCap(tx *Transaction) *big.Int {
	if !atEnv.IsAnzeon() {
		return tx.GasTipCap()
	}

	from, err := Sender(atEnv.signer, tx)
	if err == nil && atEnv.stateReader != nil && !atEnv.stateReader.IsAuthorized(from) && atEnv.headerTip != nil {
		// In Anzeon, normal account gas tip cap is determined by the block header gas tip
		return atEnv.headerTip
	}
	return tx.GasTipCap()
}

// SetCurrentBlock updates the current block header and signer.
// This should be called when the blockchain head changes.
func (env *AnzeonTipEnv) SetCurrentBlock(header *types.Header) {
	if header == nil {
		return
	}
	if env.currentBlock == nil || env.currentBlock.Root != header.Root {
		env.currentBlock = header
		if header.Root != (common.Hash{}) {
			env.currentState, _ = env.stateAt(header.Root)
		} else {
			env.currentState = nil
		}
		env.signer = types.MakeSigner(env.config, header.Number, header.Time)
	}
}

// AnzeonTipEnv manages Anzeon-specific gas tip calculation environment for transaction pool.
// It maintains state for dynamic gas tip calculations based on block headers and account authorization.
type AnzeonTipEnv struct {
	config       *params.ChainConfig
	stateAt      func(common.Hash) (*state.StateDB, error)
	currentBlock *types.Header
	currentState *state.StateDB
	baseFee      *big.Int
	signer       types.Signer
}

// SetGasTipUpdater sets the callback function to update gas tip in worker
func (bc *BlockChain) SetGasTipUpdater(updater func(*state.StateDB)) {
	bc.gasTipUpdater = updater
}

// GetBaseFee returns the current base fee.
// It returns the explicitly set base fee, or falls back to the current block's base fee.
func (env *AnzeonTipEnv) GetBaseFee() *big.Int {
	if env.baseFee != nil {
		return env.baseFee
	}
	if env.currentBlock != nil && env.currentBlock.BaseFee != nil {
		return env.currentBlock.BaseFee
	}
	return nil
}

// GetAnzeonTipCap returns the effective gas tip cap for a transaction in the Anzeon network.
// For unauthorized accounts, it returns the block header's gas tip.
// For authorized accounts (validators/minters), it returns the transaction's original gas tip cap.
func (env *AnzeonTipEnv) GetAnzeonTipCap(tx *types.Transaction) *big.Int {
	// If environment is not fully initialized, return transaction's gas tip cap
	if !env.IsAnzeon() || env.signer == nil || env.currentBlock == nil {
		return tx.GasTipCap()
	}

	// Get sender address
	from, err := types.Sender(env.signer, tx)
	if err != nil {
		return tx.GasTipCap()
	}

	// Check if sender is authorized by querying state
	// First try to use cached state, then fall back to stateAt
	// Lazy load state if not cached
	if env.currentState == nil &&
		env.stateAt != nil &&
		env.currentBlock.Root != (common.Hash{}) {
		env.currentState, _ = env.stateAt(env.currentBlock.Root)
	}

	// For unauthorized accounts, use block header's gas tip
	if env.currentState != nil &&
		!env.currentState.IsAuthorized(from) &&
		env.currentBlock.GasTip() != nil {
		return env.currentBlock.GasTip()
	}

	// For authorized accounts or if state is unavailable, use transaction's gas tip cap
	return tx.GasTipCap()
}

// NewAnzeonTipEnv creates a new AnzeonTipEnv instance for use in transaction pool.
func NewAnzeonTipEnv(config *params.ChainConfig, stateAt func(common.Hash) (*state.StateDB, error)) *AnzeonTipEnv {
	return &AnzeonTipEnv{
		config:  config,
		stateAt: stateAt,
	}
}

func (tx *AccessListTx) effectiveGasPrice(dst *big.Int, baseFee *big.Int) *big.Int {
	return dst.Set(tx.GasPrice)
}

func (tx *LegacyTx) effectiveGasPrice(dst *big.Int, baseFee *big.Int) *big.Int {
	return dst.Set(tx.GasPrice)
}

func (tx *BlobTx) effectiveGasPrice(dst *big.Int, baseFee *big.Int) *big.Int {
	if baseFee == nil {
		baseFee = big.NewInt(0)
	}
	tip := dst.Sub(tx.GasFeeCap.ToBig(), baseFee)
	if tip.Cmp(tx.GasTipCap.ToBig()) > 0 {
		tip.Set(tx.GasTipCap.ToBig())
	}
	return tip.Add(tip, baseFee)
}

func (t *Transaction) EffectiveGasPrice(ctx context.Context) (*hexutil.Big, error) {
	tx, block := t.resolve(ctx)
	if tx == nil {
		return nil, nil
	}
	// Pending tx
	if block == nil {
		return nil, nil
	}
	header, err := block.resolveHeader(ctx)
	if err != nil || header == nil {
		return nil, err
	}
	if header.BaseFee == nil {
		return (*hexutil.Big)(tx.GasPrice()), nil
	}

	gasTip := header.GasTip()

	if gasTip != nil {
		return (*hexutil.Big)(new(big.Int).Add(new(big.Int).Set(gasTip), header.BaseFee)), nil
	}

	return (*hexutil.Big)(math.BigMin(new(big.Int).Add(tx.GasTipCap(), header.BaseFee), tx.GasFeeCap())), nil
}

func (tx *DynamicFeeTx) effectiveGasPrice(dst *big.Int, baseFee *big.Int) *big.Int {
	if baseFee == nil {
		baseFee = big.NewInt(0)
	}
	tip := dst.Sub(tx.GasFeeCap, baseFee)
	if tip.Cmp(tx.GasTipCap) > 0 {
		tip.Set(tx.GasTipCap)
	}
	return tip.Add(tip, baseFee)
}

func (tx *FeeDelegateDynamicFeeTx) effectiveGasPrice(dst *big.Int, baseFee *big.Int) *big.Int {
	if baseFee == nil {
		baseFee = big.NewInt(0)
	}
	tip := dst.Sub(tx.SenderTx.GasFeeCap, baseFee)
	if tip.Cmp(tx.SenderTx.GasTipCap) > 0 {
		tip.Set(tx.SenderTx.GasTipCap)
	}
	return tip.Add(tip, baseFee)
}

func (tx *SetCodeTx) effectiveGasPrice(dst *big.Int, baseFee *big.Int) *big.Int {
	if baseFee == nil {
		baseFee = big.NewInt(0)
	}
	tip := dst.Sub(tx.GasFeeCap.ToBig(), baseFee)
	txTipCap := tx.GasTipCap.ToBig()
	if tip.Cmp(txTipCap) > 0 {
		tip.Set(txTipCap)
	}
	return tip.Add(tip, baseFee)
}

// effectiveGasPrice computes the transaction gas fee, based on the given basefee value.
//
//	price = min(gasTipCap + baseFee, gasFeeCap)
func effectiveGasPrice(tx *types.Transaction, baseFee, headerGasTip *big.Int) *big.Int {
	var fee *big.Int
	if headerGasTip != nil {
		fee = new(big.Int).Set(headerGasTip)
	} else {
		fee = tx.GasTipCap()
	}

	fee = fee.Add(fee, baseFee)
	if tx.GasFeeCapIntCmp(fee) < 0 {
		return tx.GasFeeCap()
	}
	return fee
}

// GetReceiptsByHash retrieves the receipts for all transactions in a given block.
func (bc *BlockChain) GetReceiptsByHash(hash common.Hash) types.Receipts {
	if receipts, ok := bc.receiptsCache.Get(hash); ok {
		return receipts
	}
	number := rawdb.ReadHeaderNumber(bc.db, hash)
	if number == nil {
		return nil
	}
	header := bc.GetHeader(hash, *number)
	if header == nil {
		return nil
	}

	receipts := rawdb.ReadReceipts(bc.db, hash, *number, header.Time, bc.chainConfig)
	if receipts == nil {
		return nil
	}
	bc.receiptsCache.Add(hash, receipts)
	return receipts
}

// GetReceiptsByHash returns all transaction receipts for the canonical block
// identified by the given block hash. Unlike GetBlockReceipts, this method
// only accepts a block hash and requires the block to be on the canonical chain.
func (api *BlockChainAPI) GetReceiptsByHash(ctx context.Context, blockHash common.Hash) ([]map[string]interface{}, error) {
	return api.GetBlockReceipts(ctx, rpc.BlockNumberOrHashWithHash(blockHash, true))
}

// GetBlockReceipts returns the block receipts for the given block hash or number or tag.
func (api *BlockChainAPI) GetBlockReceipts(ctx context.Context, blockNrOrHash rpc.BlockNumberOrHash) ([]map[string]interface{}, error) {
	block, err := api.b.BlockByNumberOrHash(ctx, blockNrOrHash)
	if block == nil || err != nil {
		// When the block doesn't exist, the RPC method should return JSON null
		// as per specification.
		return nil, nil
	}
	receipts, err := api.b.GetReceipts(ctx, block.Hash())
	if err != nil {
		return nil, err
	}
	txs := block.Transactions()
	if len(txs) != len(receipts) {
		return nil, fmt.Errorf("receipts length mismatch: %d vs %d", len(txs), len(receipts))
	}

	// Derive the sender.
	signer := types.MakeSigner(api.b.ChainConfig(), block.Number(), block.Time())

	result := make([]map[string]interface{}, len(receipts))
	for i, receipt := range receipts {
		result[i] = marshalReceipt(receipt, block.Hash(), block.NumberU64(), signer, txs[i], i)
	}

	return result, nil
}

func (b *EthAPIBackend) GetReceipts(ctx context.Context, hash common.Hash) (types.Receipts, error) {
	return b.eth.blockchain.GetReceiptsByHash(hash), nil
}

// GetTransactionByHash returns the transaction for the given hash
func (s *TransactionAPI) GetTransactionByHash(ctx context.Context, hash common.Hash) (*RPCTransaction, error) {
	// Try to return an already finalized transaction
	found, tx, blockHash, blockNumber, index, err := s.b.GetTransaction(ctx, hash)
	if !found {
		// No finalized transaction, try to retrieve it from the pool
		if tx := s.b.GetPoolTransaction(hash); tx != nil {
			return NewRPCPendingTransaction(tx, s.b.CurrentHeader(), s.b.ChainConfig()), nil
		}
		if err == nil {
			return nil, nil
		}
		return nil, NewTxIndexingError()
	}
	header, err := s.b.HeaderByHash(ctx, blockHash)
	if err != nil {
		return nil, err
	}
	return newRPCTransaction(tx, blockHash, blockNumber, header.Time, index, header.BaseFee, header.GasTip(), s.b.ChainConfig()), nil
}

// BlockReceipts returns the receipts of a given block number or hash.
func (ec *Client) BlockReceipts(ctx context.Context, blockNrOrHash rpc.BlockNumberOrHash) ([]*types.Receipt, error) {
	var r []*types.Receipt
	err := ec.c.CallContext(ctx, &r, "eth_getBlockReceipts", blockNrOrHash.String())
	if err == nil && r == nil {
		return nil, ethereum.NotFound
	}
	return r, err
}

// ReadReceiptsRLP retrieves all the transaction receipts belonging to a block in RLP encoding.
func ReadReceiptsRLP(db ethdb.Reader, hash common.Hash, number uint64) rlp.RawValue {
	var data []byte
	db.ReadAncients(func(reader ethdb.AncientReaderOp) error {
		// Check if the data is in ancients
		if isCanon(reader, number, hash) {
			data, _ = reader.Ancient(ChainFreezerReceiptTable, number)
			return nil
		}
		// If not, try reading from leveldb
		data, _ = db.Get(blockReceiptsKey(number, hash))
		return nil
	})
	return data
}

// GetBlockByHash returns the requested block. When fullTx is true all transactions in the block are returned in full
// detail, otherwise only the transaction hash is returned.
func (api *BlockChainAPI) GetBlockByHash(ctx context.Context, hash common.Hash, fullTx bool) (map[string]interface{}, error) {
	block, err := api.b.BlockByHash(ctx, hash)
	if block != nil {
		return api.rpcMarshalBlock(ctx, block, true, fullTx)
	}
	return nil, err
}

const (
	// txSlotSize is used to calculate how many data slots a single transaction
	// takes up based on its size. The slots are used as DoS protection, ensuring
	// that validating a new transaction remains a constant operation (in reality
	// O(maxslots), where max slots are 8 currently).
	txSlotSize = 32 * 1024

	// txMaxSize is the maximum size a single transaction can have. This field has
	// non-trivial consequences: larger transactions are significantly harder and
	// more expensive to propagate; larger transactions also take more resources
	// to validate whether they fit into the pool or not.
	// Note: increased to 256KB (8 slots) in go-stablenet to accommodate the larger MaxCodeSize (248KB).
	txMaxSize = 8 * txSlotSize // 256KB
)

const (
	// This is the target size for the packs of transactions or announcements. A
	// pack can get larger than this if a single transactions exceeds this size.
	maxTxPacketSize = 100 * 1024
)

// Size returns the true encoded storage size of the transaction, either by encoding
// and returning it, or returning a previously cached value.
func (tx *Transaction) Size() uint64 {
	if size := tx.size.Load(); size != nil {
		return size.(uint64)
	}

	// Cache miss, encode and cache.
	// Note we rely on the assumption that all tx.inner values are RLP-encoded!
	c := writeCounter(0)
	rlp.Encode(&c, &tx.inner)
	size := uint64(c)

	// For blob transactions, add the size of the blob content and the outer list of the
	// tx + sidecar encoding.
	if sc := tx.BlobTxSidecar(); sc != nil {
		size += rlp.ListSize(sc.encodedSize())
	}

	// For typed transactions, the encoding also includes the leading type byte.
	if tx.Type() != LegacyTxType {
		size += 1
	}

	tx.size.Store(size)
	return size
}

const (
	// txChanSize is the size of channel listening to NewTxsEvent.
	// The number is referenced from the size of tx pool.
	txChanSize = 4096

	// txMaxBroadcastSize is the max size of a transaction that will be broadcasted.
	// All transactions with a higher size will be announced and need to be fetched
	// by the peer.
	txMaxBroadcastSize = 4096

	protocolMaxMsgSize = 10 * 1024 * 1024 // Maximum cap on the size of a protocol message
)

// validateTx checks whether a transaction is valid according to the consensus
// rules and adheres to some heuristic limits of the local node (price and size).
func (pool *LegacyPool) validateTx(tx *types.Transaction, local bool) error {
	opts := &txpool.ValidationOptionsWithState{
		Config: pool.chainconfig,

		State: pool.currentState,

		FirstNonceGap:    nil, // Pool allows arbitrary arrival order, don't invalidate nonce gaps
		UsedAndLeftSlots: nil, // Pool has own mechanism to limit the number of transactions
		ExistingExpenditure: func(addr common.Address) *big.Int {
			if list := pool.pending[addr]; list != nil {
				return list.totalcost.ToBig()
			}
			return new(big.Int)
		},
		ExistingCost: func(addr common.Address, nonce uint64) *big.Int {
			if list := pool.pending[addr]; list != nil {
				if tx := list.txs.Get(nonce); tx != nil {
					return tx.Cost()
				}
			}
			return nil
		},
		AnzeonTipEnv: pool.anzeonTipEnv, // Enable caching of Anzeon tip cap during validation
	}
	if err := txpool.ValidateTransactionWithState(tx, pool.signer, opts); err != nil {
		return err
	}
	return pool.validateAuth(tx)
}

// validateAuth verifies that the transaction complies with code authorization
// restrictions brought by SetCode transaction type.
func (pool *LegacyPool) validateAuth(tx *types.Transaction) error {
	// Allow at most one in-flight tx for delegated accounts or those with a
	// pending authorization.
	if err := pool.checkDelegationLimit(tx); err != nil {
		return err
	}
	// For symmetry, allow at most one in-flight tx for any authority with a
	// pending transaction.
	if auths := tx.SetCodeAuthorities(); len(auths) > 0 {
		for _, auth := range auths {
			var count int
			if pending := pool.pending[auth]; pending != nil {
				count += pending.Len()
			}
			if queue := pool.queue[auth]; queue != nil {
				count += queue.Len()
			}
			if count > 1 {
				return ErrAuthorityReserved
			}
			// Because there is no exclusive lock held between different subpools
			// when processing transactions, the SetCode transaction may be accepted
			// while other transactions with the same sender address are also
			// accepted simultaneously in the other pools.
			//
			// This scenario is considered acceptable, as the rule primarily ensures
			// that attackers cannot easily stack a SetCode transaction when the sender
			// is reserved by other pools.
			if pool.reserver.Has(auth) {
				return ErrAuthorityReserved
			}
		}
	}
	return nil
}

// promoteTx adds a transaction to the pending (processable) list of transactions
// and returns whether it was inserted or an older was better.
//
// Note, this method assumes the pool lock is held!
func (pool *LegacyPool) promoteTx(addr common.Address, hash common.Hash, tx *types.Transaction) bool {
	// Try to insert the transaction into the pending queue
	if pool.pending[addr] == nil {
		pool.pending[addr] = newList(true)
	}
	list := pool.pending[addr]

	inserted, old := list.Add(tx, pool.config.PriceBump)
	if !inserted {
		// An older transaction was better, discard this
		pool.all.Remove(hash)
		pool.priced.Removed(1)
		pendingDiscardMeter.Mark(1)
		return false
	}
	// Otherwise discard any previous transaction and mark this
	if old != nil {
		pool.all.Remove(old.Hash())
		pool.priced.Removed(1)
		pendingReplaceMeter.Mark(1)
	} else {
		// Nothing was replaced, bump the pending counter
		pendingGauge.Inc(1)
	}
	// Set the potentially new pending nonce and notify any subsystems of the new tx
	pool.pendingNonces.set(addr, tx.Nonce()+1)

	// Successful promotion, bump the heartbeat
	pool.beats[addr] = time.Now()
	return true
}

func Maximum() (int, error) {
	// Retrieve the maximum allowed by dynamic OS limits
	var limit syscall.Rlimit
	if err := syscall.Getrlimit(syscall.RLIMIT_NOFILE, &limit); err != nil {
		return 0, err
	}
	// Cap it to OPEN_MAX (10240) because macos is a special snowflake
	if limit.Max > hardlimit {
		limit.Max = hardlimit
	}
	return int(limit.Max), nil
}

func (m *CommonPayload) View() wbft.View {
	return wbft.View{Sequence: m.Sequence, Round: m.Round}
}

// isTooFarFutureMessage filters out messages too far ahead in sequence or round
// This function prevents the node from processing messages that are excessively ahead,
// which could disrupt the normal flow of the consensus process
func (c *Core) isTooFarFutureMessage(view *wbft.View) bool {
	curr := c.currentView()

	if view.Sequence.Cmp(curr.Sequence) > 0 {
		// In the initial phase of block consensus, a message with a sequence number one higher than the current sequence may be received.
		if seqDiff, tooFar := c.isSequenceTooFarAhead(view.Sequence, curr.Sequence, sequenceThreshold); tooFar {
			c.logger.Trace("WBFT: future message too far ahead in sequence, dropped",
				"msg_seq", view.Sequence.String(),
				"curr_seq", curr.Sequence.String(),
				"diff", seqDiff.String(),
			)
			return true
		}
	}

	if view.Sequence.Cmp(curr.Sequence) == 0 && view.Round.Cmp(curr.Round) > 0 {
		if roundDiff, tooFar := c.isRoundTooFarAhead(view.Round, curr.Round, roundThreshold); tooFar {
			c.logger.Trace("WBFT: future message too far ahead in round, dropped",
				"msg_round", view.Round.String(),
				"curr_round", curr.Round.String(),
				"diff", roundDiff.String(),
			)
			return true
		}
	}

	return false
}

// return errInvalidMessage if the message is invalid
// return errFutureMessage if the message view is larger than current view
// return errOldMessage if the message view is smaller than current view
func (c *Core) checkMessage(msgCode uint64, view *wbft.View) error {
	if view == nil || view.Sequence == nil || view.Round == nil {
		return errInvalidMessage
	}

	// Drop the message if the view's sequence or round number is too far ahead
	// This prevents processing of messages that may disrupt consensus due to excessive lead
	if c.isTooFarFutureMessage(view) {
		return errFutureViewTooFar
	}

	if msgCode == wbfmessage.RoundChangeCode {
		// if ROUND-CHANGE message
		// check that
		// - sequence matches our current sequence
		// - round is in the future
		if view.Sequence.Cmp(c.currentView().Sequence) > 0 {
			return errFutureMessage
		} else if view.Cmp(c.currentView()) < 0 {
			return errOldMessage
		}
		return nil
	}

	// If not ROUND-CHANGE
	// check that round and sequence equals our current round and sequence
	if view.Cmp(c.currentView()) > 0 {
		return errFutureMessage
	}

	if view.Cmp(c.currentView()) < 0 {
		// save prepare and commit message to extraSeal under below condition
		// 1. view's sequence is right before current.Sequence &&
		// 2. view's round is same as prior round &&
		// 3. c.state is AcceptRequest
		if new(big.Int).Sub(c.currentView().Sequence, view.Sequence).Cmp(common.Big1) == 0 && view.Round.Cmp(c.PriorRound()) == 0 && c.state == StateAcceptRequest {
			return errExtraSealMessage
		}
		return errOldMessage
	}

	switch c.state {
	case StateAcceptRequest:
		// StateAcceptRequest only accepts msgPreprepare and msgRoundChange
		// other messages are future messages
		if msgCode > wbfmessage.PreprepareCode {
			return errFutureMessage
		}
		return nil
	case StatePreprepared:
		// StatePreprepared only accepts msgPrepare and msgRoundChange
		// message less than msgPrepare are invalid and greater are future messages
		if msgCode < wbfmessage.PrepareCode {
			return errInvalidMessage
		} else if msgCode > wbfmessage.PrepareCode {
			return errFutureMessage
		}
		return nil
	case StatePrepared:
		// StatePrepared only accepts msgCommit and msgRoundChange
		// other messages are invalid messages
		if msgCode == wbfmessage.PrepareCode {
			return errExtraSealMessage
		} else if msgCode < wbfmessage.CommitCode {
			return errInvalidMessage
		}
		return nil
	case StateCommitted:
		// for prepare, commit message with same view as current
		// return err extraSealMessage
		if msgCode >= wbfmessage.PrepareCode {
			return errExtraSealMessage
		}
		// StateCommit rejects all messages other than msgRoundChange
		return errInvalidMessage
	}
	return nil
}

// isSequenceTooFarAhead returns true if the sequence difference exceeds the threshold
func (c *Core) isSequenceTooFarAhead(viewSeq, currSeq *big.Int, threshold int64) (*big.Int, bool) {
	seqDiff := new(big.Int).Sub(viewSeq, currSeq)
	return seqDiff, seqDiff.Cmp(big.NewInt(threshold)) > 0
}

// isRoundTooFarAhead returns true if the round difference exceeds the threshold
func (c *Core) isRoundTooFarAhead(viewRound, currRound *big.Int, threshold int64) (*big.Int, bool) {
	roundDiff := new(big.Int).Sub(viewRound, currRound)
	return roundDiff, roundDiff.Cmp(big.NewInt(threshold)) > 0
}

func toNegatePriority(msgCode uint64, view *wbft.View) int64 {
	if msgCode == wbfmessage.RoundChangeCode {
		// For msgRoundChange, set the message priority based on its sequence
		return -int64(view.Sequence.Uint64() * 1000)
	}
	// FIXME: round will be reset as 0 while new sequence
	// 10 * Round limits the range of message code is from 0 to 9
	// 1000 * Sequence limits the range of round is from 0 to 99
	return -int64(view.Sequence.Uint64()*1000 + view.Round.Uint64()*10 + uint64(msgPriority[msgCode]))
}

// startNewRound starts a new round. if round equals to 0, it means to starts a new sequence
func (c *Core) startNewRound(round *big.Int) {
	c.currentMutex.Lock()
	defer c.currentMutex.Unlock()

	var logger log.Logger
	if c.current == nil {
		logger = c.logger.New("old.round", -1, "old.seq", 0)
	} else {
		logger = c.currentLogger(false, nil)
	}
	logger = logger.New("target.round", round)

	roundChange := false

	// Try to get last proposal
	lastProposal, lastProposer := c.backend.LastProposal()
	if lastProposal != nil {
		logger = logger.New("lastProposal.number", lastProposal.Number().Uint64(), "lastProposal.hash", lastProposal.Hash())
	}

	logger.Debug("WBFT: initialize new round")

	if c.current == nil {
		logger.Debug("WBFT: start at the initial round")
	} else if lastProposal.Number().Cmp(c.current.Sequence()) >= 0 {
		diff := new(big.Int).Sub(lastProposal.Number(), c.current.Sequence())
		sequenceMeter.Mark(new(big.Int).Add(diff, common.Big1).Int64())

		if !c.consensusTimestamp.IsZero() {
			consensusTimer.UpdateSince(c.consensusTimestamp)
			c.consensusTimestamp = time.Time{}
		}
		logger.Debug("WBFT: catch up last block proposal")
	} else if lastProposal.Number().Cmp(big.NewInt(c.current.Sequence().Int64()-1)) == 0 {
		if round.Cmp(common.Big0) == 0 {
			// same seq and round, don't need to start new round
			logger.Debug("WBFT: same round, no need to start new round")
			return
		} else if round.Cmp(c.current.Round()) < 0 {
			logger.Warn("WBFT: next round is inferior to current round")
			return
		}
		roundChange = true
	} else {
		logger.Warn("WBFT: next sequence is before last block proposal")
		return
	}

	var oldLogger log.Logger
	if c.current == nil {
		oldLogger = c.logger.New("old.round", -1, "old.seq", 0)
	} else {
		oldLogger = c.logger.New("old.round", c.current.Round().Uint64(), "old.sequence", c.current.Sequence().Uint64(), "old.state", c.state.String(), "old.proposer", c.valSet.GetProposer())
	}

	if c.current != nil && round.Cmp(c.current.Round()) > 0 {
		roundMeter.Mark(new(big.Int).Sub(round, c.current.Round()).Int64())
	}

	// Create next view
	var newView *wbft.View
	var nextValSet wbft.ValidatorSet
	if roundChange {
		newView = &wbft.View{
			Sequence: new(big.Int).Set(c.current.Sequence()),
			Round:    new(big.Int).Set(round),
		}
		nextValSet = c.valSet
	} else {
		newView = &wbft.View{
			Sequence: new(big.Int).Add(lastProposal.Number(), common.Big1),
			Round:    new(big.Int),
		}
		nextValSet = c.backend.Validators(lastProposal)

		// Add extra seal that contributed to consensus
		c.addEffectiveSealToExtraSeal()
	}

	// New snapshot for new round
	c.updateRoundState(nextValSet, newView, roundChange)

	// Calculate new proposer
	c.valSet.CalcProposer(lastProposer, newView.Round.Uint64())
	c.setState(StateAcceptRequest)

	// Update RoundChangeSet by deleting older round messages
	if round.Uint64() == 0 {
		c.WBFTPreparedPrepares = nil
		c.roundChangeSet = newRoundChangeSet(c.valSet)
		c.ClearExtraSeals(lastProposal.Number())
	} else {
		// Clear earlier round messages
		c.roundChangeSet.ClearLowerThan(round)
	}
	c.roundChangeSet.NewRound(round)

	c.backend.NotifyNewRound(round)

	// the order of NotifyNewRound() and newRoundChangeTimer() does not matter on actual consensus, but
	// it matters on multi-engine test, so we keep the order as it is
	c.newRoundChangeTimer()

	oldLogger.Info("WBFT: start new round", "next.round", newView.Round, "next.seq", newView.Sequence, "next.proposer", c.valSet.GetProposer(), "next.valSet", c.valSet.List(), "next.size", c.valSet.Size(), "next.IsProposer", c.IsProposer())
}

func (c *Core) isTooFarFutureMessage(view *wbft.View) bool {
	curr := c.currentView()

	if view.Sequence.Cmp(curr.Sequence) > 0 {
		// In the initial phase of block consensus, a message with a sequence number one higher than the current sequence may be received.
		if seqDiff, tooFar := c.isSequenceTooFarAhead(view.Sequence, curr.Sequence, sequenceThreshold); tooFar {
			c.logger.Trace("WBFT: future message too far ahead in sequence, dropped",
				"msg_seq", view.Sequence.String(),
				"curr_seq", curr.Sequence.String(),
				"diff", seqDiff.String(),
			)
			return true
		}
	}

	if view.Sequence.Cmp(curr.Sequence) == 0 && view.Round.Cmp(curr.Round) > 0 {
		if roundDiff, tooFar := c.isRoundTooFarAhead(view.Round, curr.Round, roundThreshold); tooFar {
			c.logger.Trace("WBFT: future message too far ahead in round, dropped",
				"msg_round", view.Round.String(),
				"curr_round", curr.Round.String(),
				"diff", roundDiff.String(),
			)
			return true
		}
	}

	return false
}

func (c *Core) isSequenceTooFarAhead(viewSeq, currSeq *big.Int, threshold int64) (*big.Int, bool) {
	seqDiff := new(big.Int).Sub(viewSeq, currSeq)
	return seqDiff, seqDiff.Cmp(big.NewInt(threshold)) > 0
}

// initializeGovCouncil initializes the GovCouncil contract storage.
// Reconciles blacklist and authorized account addresses from two sources:
// params (chain config) and alloc.Extra bits (genesis account state).
// The final sets are the union of both sources, applied to both alloc.Extra
// and the contract storage slots.
func initializeGovCouncil(govCouncilAddress common.Address, param map[string]string, alloc *types.GenesisAlloc) ([]params.StateParam, error) {
	// Initialize GovBase first
	sp, err := initializeBase(govCouncilAddress, param)
	if err != nil {
		return sp, err
	}

	// Build initial sets from params.
	blacklistSet, err := parseParamAddresses(param[GOV_COUNCIL_PARAM_BLACKLIST])
	if err != nil {
		return nil, fmt.Errorf("`systemContracts.govCouncil.params.blacklist`: %w", err)
	}
	authorizedSet, err := parseParamAddresses(param[GOV_COUNCIL_PARAM_AUTHORIZED_ACCOUNTS])
	if err != nil {
		return nil, fmt.Errorf("`systemContracts.govCouncil.params.authorizedAccounts`: %w", err)
	}

	if alloc != nil {
		// Merge Extra bits from alloc into the sets (union with params).
		// Zero addresses are skipped: unlike the params path which rejects them
		// as a configuration error, a zero address in alloc may exist for other
		// purposes and is simply not relevant to blacklist/authorized registration.
		for addr, account := range *alloc {
			if addr == (common.Address{}) {
				continue
			}
			if types.IsBlacklisted(account.Extra) {
				blacklistSet[addr] = struct{}{}
			}
			if types.IsAuthorized(account.Extra) {
				authorizedSet[addr] = struct{}{}
			}
		}

		// Sync alloc.Extra bits to reflect the final merged sets.
		// Addresses present only in params are added as new alloc entries.
		for addr := range blacklistSet {
			account := (*alloc)[addr]
			account.Extra = types.SetBlacklisted(account.Extra)
			(*alloc)[addr] = account
		}
		for addr := range authorizedSet {
			account := (*alloc)[addr]
			account.Extra = types.SetAuthorized(account.Extra)
			(*alloc)[addr] = account
		}
	}

	// Skip slot initialization for empty sets to avoid writing a zero-length
	// array entry to contract storage unnecessarily.
	if len(blacklistSet) > 0 {
		blacklistParams := initializeAddressSet(
			govCouncilAddress,
			common.HexToHash(SLOT_GOV_COUNCIL_currentBlacklist_values),
			common.HexToHash(SLOT_GOV_COUNCIL_currentBlacklist_positions),
			blacklistSet,
		)
		sp = append(sp, blacklistParams...)
	}
	if len(authorizedSet) > 0 {
		authorizedAccountParams := initializeAddressSet(
			govCouncilAddress,
			common.HexToHash(SLOT_GOV_COUNCIL_currentAuthorizedAccounts_values),
			common.HexToHash(SLOT_GOV_COUNCIL_currentAuthorizedAccounts_positions),
			authorizedSet,
		)
		sp = append(sp, authorizedAccountParams...)
	}

	// Initialize __accountManager
	sp = append(sp, params.StateParam{
		Address: govCouncilAddress,
		Key:     common.HexToHash(SLOT_GOV_COUNCIL_accountManager),
		Value:   common.BytesToHash(params.AccountManagerAddress.Bytes()),
	})

	return sp, nil
}

// Extra field bit masks for StateAccount.
// The Extra field is a 64-bit value where each bit can represent a specific state or property.
//
// Bit positions (MSB to LSB):
//   - Bit 63 (0x8000000000000000): Blacklisted
//   - Bit 62 (0x4000000000000000): Authorized
//   - Bit 61 (0x2000000000000000): Reserved for future use
//   - ... (add more as needed)
const (
	// AccountExtraMaskBlacklisted defines the bit mask used to mark an account as blacklisted (bit 63, MSB).
	AccountExtraMaskBlacklisted uint64 = 1 << 63

	// AccountExtraMaskAuthorized defines the bit mask used to mark an account as authorized (bit 62).
	AccountExtraMaskAuthorized uint64 = 1 << 62

	// AccountExtraMaskC defines the bit mask used to mark ... (bit 61)
	// Uncomment and adjust as needed:
	// AccountExtraMaskC uint64 = 1 << 61

	// AccountExtraValidMask is the union of all defined bit masks.
	// When adding a new bit mask, it must also be included here;
	// otherwise ValidateExtra will reject accounts that use the new bit.
	AccountExtraValidMask uint64 = AccountExtraMaskBlacklisted | AccountExtraMaskAuthorized
)

        // Update account extra field via AccountManager
        (bool _success, ) = __accountManager.call(abi.encodeCall(IAccountManager.authorize, (account)));
        if (!_success) {
            emit ProposalExecutionSkipped(account, proposalId, "GovCouncil: authorize call failed");
            return false;
        }

        _currentAuthorizedAccounts.add(account);

        emit AuthorizedAccountAdded(account, proposalId);

        return true;
    }

    /**
     * @notice Remove address from authorized account list (internal)
     * @dev Re-validates state at execution time
     * @param account Address to unauthorize
     * @param proposalId Proposal ID that triggered this
     * @return success True if successful, false if not authorized
     */
    function _removeFromAuthorizedAccount(address account, uint256 proposalId) private returns (bool success) {
        // Re-validate at execution time
        if (!_currentAuthorizedAccounts.contains(account)) {
            // Not in authorized list - emit event and return false to terminate proposal
            emit ProposalExecutionSkipped(account, proposalId, "NOT_AUTHORIZED");
            return false;
        }

        // Update account extra field via AccountManager
        (bool _success, ) = __accountManager.call(abi.encodeCall(IAccountManager.unAuthorize, (account)));
        if (!_success) {
            emit ProposalExecutionSkipped(account, proposalId, "GovCouncil: unAuthorize call failed");
            return false;
        }

        _currentAuthorizedAccounts.remove(account);

        emit AuthorizedAccountRemoved(account, proposalId);

        return true;
    }

    // ========================================
    // BLACKLIST: Query Functions
    // ========================================

    /**
     * @notice Check if address is currently blacklisted
     * @param account Address to check
     * @return isBlacklisted True if currently in blacklist
     */
    function isBlacklisted(address account) external view returns (bool) {
        if (account == address(0)) {
            revert AddressSetLib.ZeroAddressNotAllowed();
        }

        (bool _success, bytes memory result) = __accountManager.staticcall(
            abi.encodeCall(IAccountManager.isBlacklisted, (account))
        );
        require(_success, "GovCouncil: isBlacklisted call failed");
        return abi.decode(result, (bool));
    }

    /**
     * @notice Get total number of currently blacklisted addresses
     * @return count Number of addresses
     */
    function getBlacklistCount() external view returns (uint256) {
        return _currentBlacklist.length();
    }

    /**
     * @notice Get blacklisted address at specific index
     * @dev Use with getBlacklistCount() for iteration
     * @param index Index to query (0-based)
     * @return account Address at index
     */
    function getBlacklistedAddress(uint256 index) external view returns (address) {
        return _currentBlacklist.at(index);
    }

    /**
     * @notice Get range of blacklisted addresses (pagination)
     * @dev Recommended for large lists. O(n) where n = end - start + 1
     * @param startIndex Start index (inclusive)
     * @param endIndex End index (inclusive)
     * @return addresses Array of addresses in range
     */
    function getBlacklistRange(uint256 startIndex, uint256 endIndex)
        external
        view
        returns (address[] memory)
    {
        return _currentBlacklist.valuesInRange(startIndex, endIndex);
    }

    /**
     * @notice Get all currently blacklisted addresses
     * @dev WARNING: Can be expensive for large lists. Use getBlacklistRange() for pagination.
     * @return addresses Array of all blacklisted addresses
     */
    function getAllBlacklisted() external view returns (address[] memory) {
        return _currentBlacklist.values();
    }

    // ========================================
    // AUTHORIZED ACCOUNT: Query Functions
    // ========================================

    /**
     * @notice Check if address is currently in authorized account list
     */
    function isAuthorizedAccount(address account) external view returns (bool) {
        if (account == address(0)) {
            revert AddressSetLib.ZeroAddressNotAllowed();
        }

        (bool _success, bytes memory result) = __accountManager.staticcall(
            abi.encodeCall(IAccountManager.isAuthorized, (account))
        );
        require(_success, "GovCouncil: isAuthorized call failed");
        return abi.decode(result, (bool));
    }

    /**
     * @notice Get total number of authorized accounts
     */
    function getAuthorizedAccountCount() external view returns (uint256) {
        return _currentAuthorizedAccounts.length();
    }

    /**
     * @notice Get authorized account address at specific index
     */
    function getAuthorizedAccountAddress(uint256 index) external view returns (address) {
        return _currentAuthorizedAccounts.at(index);
    }

    /**
     * @notice Get range of authorized account addresses (pagination)
     */
    function getAuthorizedAccountRange(uint256 startIndex, uint256 endIndex)
        external
        view
        returns (address[] memory)
    {
        return _currentAuthorizedAccounts.valuesInRange(startIndex, endIndex);
    }

    /**
     * @notice Get all authorized account addresses
     */
    function getAllAuthorizedAccounts() external view returns (address[] memory) {
        return _currentAuthorizedAccounts.values();
    }
}

contract GovCouncil is GovBase {
    using AddressSetLib for AddressSetLib.AddressSet;

    // ========== Storage ==========

    // Current active lists (O(1) operations)
    AddressSetLib.AddressSet private _currentBlacklist;
    AddressSetLib.AddressSet private _currentAuthorizedAccounts;
    address private __accountManager;

    // ========== Action Types ==========

    // Action types for single operations
    bytes32 public constant ACTION_ADD_BLACKLIST = keccak256("ADD_BLACKLIST");
    bytes32 public constant ACTION_REMOVE_BLACKLIST = keccak256("REMOVE_BLACKLIST");
    bytes32 public constant ACTION_ADD_AUTHORIZED_ACCOUNT = keccak256("ADD_AUTHORIZED_ACCOUNT");
    bytes32 public constant ACTION_REMOVE_AUTHORIZED_ACCOUNT = keccak256("REMOVE_AUTHORIZED_ACCOUNT");

    // Action types for batch operations
    bytes32 public constant ACTION_ADD_BLACKLIST_BATCH = keccak256("ADD_BLACKLIST_BATCH");
    bytes32 public constant ACTION_REMOVE_BLACKLIST_BATCH = keccak256("REMOVE_BLACKLIST_BATCH");
    bytes32 public constant ACTION_ADD_AUTHORIZED_ACCOUNT_BATCH = keccak256("ADD_AUTHORIZED_ACCOUNT_BATCH");
    bytes32 public constant ACTION_REMOVE_AUTHORIZED_ACCOUNT_BATCH = keccak256("REMOVE_AUTHORIZED_ACCOUNT_BATCH");

    // ========== Events ==========

    /// @notice Emitted when address is added to blacklist
    /// @param account The blacklisted address
    /// @param proposalId The proposal that caused this change
    event AddressBlacklisted(address indexed account, uint256 indexed proposalId);

    /// @notice Emitted when address is removed from blacklist
    /// @param account The address removed from blacklist
    /// @param proposalId The proposal that caused this change
    event AddressUnblacklisted(address indexed account, uint256 indexed proposalId);

    /// @notice Emitted when address is added to authorized account list
    /// @param account The authorized account address
    /// @param proposalId The proposal that caused this change
    event AuthorizedAccountAdded(address indexed account, uint256 indexed proposalId);

    /// @notice Emitted when address is removed from authorized account list
    /// @param account The authorized account address
    /// @param proposalId The proposal that caused this change
    event AuthorizedAccountRemoved(address indexed account, uint256 indexed proposalId);

    /// @notice Emitted when proposal execution is skipped because target already exists
    /// @param account The account address
    /// @param proposalId The proposal that was skipped
    /// @param reason The reason for skipping (e.g., "ALREADY_BLACKLISTED", "NOT_IN_BLACKLIST")
    event ProposalExecutionSkipped(address indexed account, uint256 indexed proposalId, string reason);

    // ========== Custom Errors ==========

    error AlreadyInBlacklist();
    error NotInBlacklist();
    error AlreadyInAuthorizedAccountList();
    error NotInAuthorizedAccountList();

    // ========================================
    // BLACKLIST: Proposal Functions
    // ========================================

    /**
     * @notice Propose to add an address to blacklist
     * @dev Creates governance proposal. Requires approval to execute.
     *
     * Security checks:
     * - Zero address validation
     * - Duplicate prevention
     * - Member-only access (via GovBase)
     *
     * @param account Address to blacklist
     * @return proposalId The created proposal ID
     */
    function proposeAddBlacklist(address account)
        external
        onlyActiveMember
        returns (uint256 proposalId)
    {
        // Security: Validate address
        if (account == address(0)) {
            revert AddressSetLib.ZeroAddressNotAllowed();
        }

        // Security: Prevent duplicates
        if (_currentBlacklist.contains(account)) {
            revert AlreadyInBlacklist();
        }

        return _createProposal(ACTION_ADD_BLACKLIST, abi.encode(account));
    }

    /**
     * @notice Propose to remove an address from blacklist
     * @dev Creates governance proposal. Requires approval to execute.
     *
     * Security checks:
     * - Existence validation
     * - Member-only access (via GovBase)
     *
     * @param account Address to remove from blacklist
     * @return proposalId The created proposal ID
     */
    function proposeRemoveBlacklist(address account)
        external
        onlyActiveMember
        returns (uint256 proposalId)
    {
        // Security: Validate existence
        if (!_currentBlacklist.contains(account)) {
            revert NotInBlacklist();
        }

        return _createProposal(ACTION_REMOVE_BLACKLIST, abi.encode(account));
    }

    /**
     * @notice Propose to add multiple addresses to blacklist (batch operation)
     * @dev More gas-efficient than multiple single proposals
     *
     * @param accounts Array of addresses to blacklist
     * @return proposalId The created proposal ID
     */
    function proposeAddBlacklistBatch(address[] calldata accounts)
        external
        onlyActiveMember
        returns (uint256 proposalId)
    {
        // Validate all addresses first
        for (uint256 i = 0; i < accounts.length; i++) {
            if (accounts[i] == address(0)) {
                revert AddressSetLib.ZeroAddressNotAllowed();
            }
            if (_currentBlacklist.contains(accounts[i])) {
                revert AlreadyInBlacklist();
            }
        }

        return _createProposal(ACTION_ADD_BLACKLIST_BATCH, abi.encode(accounts));
    }

// GenerateChainWithGenesis is a wrapper of GenerateChain which will initialize
// genesis block to database first according to the provided genesis specification
// then generate chain on top.
func GenerateChainWithGenesis(genesis *Genesis, engine consensus.Engine, n int, gen func(int, *BlockGen)) (ethdb.Database, []*types.Block, []types.Receipts) {
	db := rawdb.NewMemoryDatabase()
	triedb := triedb.NewDatabase(db, triedb.HashDefaults)
	defer triedb.Close()
	// before committing genesis, generate contract allocation and extraData for anzeon config
	if genesis.Config.AnzeonEnabled() {
		genesis.ExtraData, _ = wbft.CreateInitialExtraData(genesis.Config.Anzeon)

		_ = InjectContracts(genesis, genesis.Config)
	}
	_, err := genesis.Commit(db, triedb)
	if err != nil {
		panic(err)
	}
	blocks, receipts := GenerateChain(genesis.Config, genesis.ToBlock(), engine, db, n, gen)
	return db, blocks, receipts
}

func BytesToHash(b []byte) Hash {
	var h Hash
	h.SetBytes(b)
	return h
}

// P256VERIFY (secp256r1 signature verification)
// implemented as a native contract
type p256Verify struct{}

// PrecompiledContractsP256Verify contains the precompiled Ethereum
// contract specified in EIP-7212. This is exported for testing purposes.
var PrecompiledContractsP256Verify = map[common.Address]PrecompiledContract{
	common.BytesToAddress([]byte{0x1, 0x00}): &p256Verify{},
}

// runBn256Add implements the Bn256Add precompile, referenced by both
// Byzantium and Istanbul operations.
func runBn256Add(input []byte) ([]byte, error) {
	x, err := newCurvePoint(getData(input, 0, 64))
	if err != nil {
		return nil, err
	}
	y, err := newCurvePoint(getData(input, 64, 64))
	if err != nil {
		return nil, err
	}
	res := new(bn256.G1)
	res.Add(x, y)
	return res.Marshal(), nil
}

type PrecompiledContract interface {
	RequiredGas(input []byte) uint64  // RequiredPrice calculates the contract gas use
	Run(input []byte) ([]byte, error) // Run runs the precompiled contract
}

func (a Address) Hex() string {
	return string(a.checksumHex())
}

function claimBurnRefund() external {
    uint256 amount = refundableBalance[msg.sender];
    if (amount == 0) revert NoRefundAvailable();

    refundableBalance[msg.sender] = 0;

    (bool success, ) = msg.sender.call{value: amount}("");
    if (!success) revert RefundTransferFailed();

    emit BurnRefundClaimed(msg.sender, amount);
}

function _cleanupBurnDeposit(uint256 proposalId) internal {
    BurnProposalData memory data = burnProposals[proposalId];
    if (data.amount == 0) return; // idempotent: already cleaned or not a burn proposal

    // For Executed proposals, _safeBurn already decremented burnBalance on success.
    // For Failed proposals, _safeBurn's try-catch returned false without modifying burnBalance.
    // For Cancelled/Expired/Rejected, _safeBurn was never called.
    ProposalStatus status = proposals[proposalId].status;
    if (status != ProposalStatus.Executed) {
        // Move from burnBalance to refundableBalance (no external calls)
        burnBalance[data.requester] -= data.amount;
        refundableBalance[data.requester] += data.amount;
        emit BurnDepositRefunded(proposalId, data.requester, data.amount);
    }

    // Clean up proposal data in all cases
    delete burnProposals[proposalId];
}

// GetRefund returns the current value of the refund counter.
func (s *StateDB) GetRefund() uint64 {
	return s.refund
}

// AddRefund adds gas to the refund counter
func (s *StateDB) AddRefund(gas uint64) {
	s.journal.append(refundChange{prev: s.refund})
	s.refund += gas
}

// LoadChainConfigWithOverride loads the chain configuration from the database if present,
// otherwise returns the config from the provided genesis specification, with overrides applied.
func LoadChainConfigWithOverride(db ethdb.Database, genesis *Genesis, overrides *ChainOverrides) (*params.ChainConfig, error) {
	if genesis != nil && genesis.Config == nil {
		return params.AllEthashProtocolChanges, errGenesisNoConfig
	}

	stored := rawdb.ReadCanonicalHash(db, 0)
	// If no genesis block is stored, use the provided genesis or default
	if (stored == common.Hash{}) {
		if genesis == nil {
			genesis = DefaultStableNetMainnetGenesisBlock()
		}
		if genesis.Config == nil {
			return params.AllEthashProtocolChanges, errGenesisNoConfig
		}
		applyOverrides(genesis.Config, overrides)
		return genesis.Config, nil
	}

	// If a canonical genesis already exists and a genesis is provided, ensure
	// the provided genesis does not point to a different chain.
	if genesis != nil {
		applyOverrides(genesis.Config, overrides)
		if err := validateAnzeonGenesisConfig(genesis.Config); err != nil {
			return nil, err
		}
		if err := initializeAnzeonGenesis(genesis); err != nil {
			return genesis.Config, err
		}
		hash := genesis.ToBlock().Hash()
		if hash != stored {
			return genesis.Config, &GenesisMismatchError{Stored: stored, New: hash}
		}
	}

	// Genesis exists, get the config
	newcfg := genesis.configOrDefault(stored)
	applyOverrides(newcfg, overrides)

	// Validate fork order
	if err := newcfg.CheckConfigForkOrder(); err != nil {
		return newcfg, err
	}

	// Check if there's a stored config in the database
	storedcfg := rawdb.ReadChainConfig(db, stored)
	if storedcfg != nil {
		// Special case: private network - use stored config with overrides
		if genesis == nil && stored != params.MainnetGenesisHash && stored != params.StableNetMainnetGenesisHash {
			newcfg = storedcfg
			applyOverrides(newcfg, overrides)
		}
	}

	return newcfg, nil
}

// LoadChainConfig loads the stored chain config if it is already present in
// database, otherwise, return the config in the provided genesis specification.
func LoadChainConfig(db ethdb.Database, genesis *Genesis) (*params.ChainConfig, error) {
	// Load the stored chain config from the database. It can be nil
	// in case the database is empty. Notably, we only care about the
	// chain config corresponds to the canonical chain.
	stored := rawdb.ReadCanonicalHash(db, 0)
	if stored != (common.Hash{}) {
		storedcfg := rawdb.ReadChainConfig(db, stored)
		if storedcfg != nil {
			return storedcfg, nil
		}
	}
	// Load the config from the provided genesis specification
	if genesis != nil {
		// Reject invalid genesis spec without valid chain config
		if genesis.Config == nil {
			return nil, errGenesisNoConfig
		}
		// If the canonical genesis header is present, but the chain
		// config is missing(initialize the empty leveldb with an
		// external ancient chain segment), ensure the provided genesis
		// is matched.
		if stored != (common.Hash{}) && genesis.ToBlock().Hash() != stored {
			return nil, &GenesisMismatchError{stored, genesis.ToBlock().Hash()}
		}
		return genesis.Config, nil
	}
	// There is no stored chain config and no new config provided,
	// In this case the default chain config(mainnet) will be used
	return params.StableNetMainnetChainConfig, nil
}

// CheckConfigForkOrder checks that we don't "skip" any forks, geth isn't pluggable enough
// to guarantee that forks can be implemented in a different order than on official networks
func (c *ChainConfig) CheckConfigForkOrder() error {
	type fork struct {
		name      string
		block     *big.Int // forks up to - and including the merge - were defined with block numbers
		timestamp *uint64  // forks after the merge are scheduled using timestamps
		optional  bool     // if true, the fork may be nil and next fork is still allowed
	}
	var lastFork fork
	for _, cur := range []fork{
		{name: "homesteadBlock", block: c.HomesteadBlock},
		{name: "daoForkBlock", block: c.DAOForkBlock, optional: true},
		{name: "eip150Block", block: c.EIP150Block},
		{name: "eip155Block", block: c.EIP155Block},
		{name: "eip158Block", block: c.EIP158Block},
		{name: "byzantiumBlock", block: c.ByzantiumBlock},
		{name: "constantinopleBlock", block: c.ConstantinopleBlock},
		{name: "petersburgBlock", block: c.PetersburgBlock},
		{name: "istanbulBlock", block: c.IstanbulBlock},
		{name: "muirGlacierBlock", block: c.MuirGlacierBlock, optional: true},
		{name: "berlinBlock", block: c.BerlinBlock},
		{name: "londonBlock", block: c.LondonBlock},
		{name: "arrowGlacierBlock", block: c.ArrowGlacierBlock, optional: true},
		{name: "grayGlacierBlock", block: c.GrayGlacierBlock, optional: true},
		{name: "applepieBlock", block: c.ApplepieBlock, optional: true},
		{name: "bohoBlock", block: c.BohoBlock, optional: true},
		{name: "mergeNetsplitBlock", block: c.MergeNetsplitBlock, optional: true},
		{name: "shanghaiTime", timestamp: c.ShanghaiTime, optional: true},
		{name: "cancunTime", timestamp: c.CancunTime, optional: true},
		{name: "pragueTime", timestamp: c.PragueTime, optional: true},
		{name: "verkleTime", timestamp: c.VerkleTime, optional: true},
	} {
		if lastFork.name != "" {
			switch {
			// Non-optional forks must all be present in the chain config up to the last defined fork
			case lastFork.block == nil && lastFork.timestamp == nil && (cur.block != nil || cur.timestamp != nil):
				if cur.block != nil {
					return fmt.Errorf("unsupported fork ordering: %v not enabled, but %v enabled at block %v",
						lastFork.name, cur.name, cur.block)
				} else {
					return fmt.Errorf("unsupported fork ordering: %v not enabled, but %v enabled at timestamp %v",
						lastFork.name, cur.name, *cur.timestamp)
				}

			// Fork (whether defined by block or timestamp) must follow the fork definition sequence
			case (lastFork.block != nil && cur.block != nil) || (lastFork.timestamp != nil && cur.timestamp != nil):
				if lastFork.block != nil && lastFork.block.Cmp(cur.block) > 0 {
					return fmt.Errorf("unsupported fork ordering: %v enabled at block %v, but %v enabled at block %v",
						lastFork.name, lastFork.block, cur.name, cur.block)
				} else if lastFork.timestamp != nil && *lastFork.timestamp > *cur.timestamp {
					return fmt.Errorf("unsupported fork ordering: %v enabled at timestamp %v, but %v enabled at timestamp %v",
						lastFork.name, *lastFork.timestamp, cur.name, *cur.timestamp)
				}

				// Timestamp based forks can follow block based ones, but not the other way around
				if lastFork.timestamp != nil && cur.block != nil {
					return fmt.Errorf("unsupported fork ordering: %v used timestamp ordering, but %v reverted to block ordering",
						lastFork.name, cur.name)
				}
			}
		}
		// If it was optional and not set, then ignore it
		if !cur.optional || (cur.block != nil || cur.timestamp != nil) {
			lastFork = cur
		}
	}
	return nil
}

// ChainConfig is the core config which determines the blockchain settings.
//
// ChainConfig is stored in the database on a per block basis. This means
// that any network, identified by its genesis block, can have its own
// set of configuration options.
type ChainConfig struct {
	ChainID *big.Int `json:"chainId"` // chainId identifies the current chain and is used for replay protection

	HomesteadBlock *big.Int `json:"homesteadBlock,omitempty"` // Homestead switch block (nil = no fork, 0 = already homestead)

	DAOForkBlock   *big.Int `json:"daoForkBlock,omitempty"`   // TheDAO hard-fork switch block (nil = no fork)
	DAOForkSupport bool     `json:"daoForkSupport,omitempty"` // Whether the nodes supports or opposes the DAO hard-fork

	// EIP150 implements the Gas price changes (https://github.com/ethereum/EIPs/issues/150)
	EIP150Block *big.Int `json:"eip150Block,omitempty"` // EIP150 HF block (nil = no fork)
	EIP155Block *big.Int `json:"eip155Block,omitempty"` // EIP155 HF block
	EIP158Block *big.Int `json:"eip158Block,omitempty"` // EIP158 HF block

	ByzantiumBlock      *big.Int `json:"byzantiumBlock,omitempty"`      // Byzantium switch block (nil = no fork, 0 = already on byzantium)
	ConstantinopleBlock *big.Int `json:"constantinopleBlock,omitempty"` // Constantinople switch block (nil = no fork, 0 = already activated)
	PetersburgBlock     *big.Int `json:"petersburgBlock,omitempty"`     // Petersburg switch block (nil = same as Constantinople)
	IstanbulBlock       *big.Int `json:"istanbulBlock,omitempty"`       // Istanbul switch block (nil = no fork, 0 = already on istanbul)
	MuirGlacierBlock    *big.Int `json:"muirGlacierBlock,omitempty"`    // Eip-2384 (bomb delay) switch block (nil = no fork, 0 = already activated)
	BerlinBlock         *big.Int `json:"berlinBlock,omitempty"`         // Berlin switch block (nil = no fork, 0 = already on berlin)
	LondonBlock         *big.Int `json:"londonBlock,omitempty"`         // London switch block (nil = no fork, 0 = already on london)
	ArrowGlacierBlock   *big.Int `json:"arrowGlacierBlock,omitempty"`   // Eip-4345 (bomb delay) switch block (nil = no fork, 0 = already activated)
	GrayGlacierBlock    *big.Int `json:"grayGlacierBlock,omitempty"`    // Eip-5133 (bomb delay) switch block (nil = no fork, 0 = already activated)
	MergeNetsplitBlock  *big.Int `json:"mergeNetsplitBlock,omitempty"`  // Virtual fork after The Merge to use as a network splitter
	ApplepieBlock       *big.Int `json:"applepieBlock,omitempty"`       // Applepie switch block (nil = no fork, 0 = already on Applepie)
	BohoBlock           *big.Int `json:"bohoBlock,omitempty"`           // Boho switch block (nil = no fork, 0 = already on Boho)

	// Fork scheduling was switched from blocks to timestamps here

	ShanghaiTime *uint64 `json:"shanghaiTime,omitempty"` // Shanghai switch time (nil = no fork, 0 = already on shanghai)
	CancunTime   *uint64 `json:"cancunTime,omitempty"`   // Cancun switch time (nil = no fork, 0 = already on cancun)
	PragueTime   *uint64 `json:"pragueTime,omitempty"`   // Prague switch time (nil = no fork, 0 = already on prague)
	VerkleTime   *uint64 `json:"verkleTime,omitempty"`   // Verkle switch time (nil = no fork, 0 = already on verkle)

	// TerminalTotalDifficulty is the amount of total difficulty reached by
	// the network that triggers the consensus upgrade.
	TerminalTotalDifficulty *big.Int `json:"terminalTotalDifficulty,omitempty"`

	// TerminalTotalDifficultyPassed is a flag specifying that the network already
	// passed the terminal total difficulty. Its purpose is to disable legacy sync
	// even without having seen the TTD locally (safer long term).
	TerminalTotalDifficultyPassed bool `json:"terminalTotalDifficultyPassed,omitempty"`

	// Various consensus engines
	Ethash *EthashConfig `json:"ethash,omitempty"`
	Clique *CliqueConfig `json:"clique,omitempty"`

	Anzeon      *AnzeonConfig `json:"anzeon,omitempty"`
	Boho        *AnzeonConfig `json:"boho,omitempty"`
	Transitions []Transition  `json:"transitions,omitempty"`
}

// overrideConfig returns a copy of original with forks enabled by override enabled,
// along with a boolean that indicates whether the copy is canonical (equivalent to the original).
// Note: the Clique-part is _not_ deep copied
func overrideConfig(original *params.ChainConfig, override *params.ChainConfig) (*params.ChainConfig, bool) {
	copy := new(params.ChainConfig)
	*copy = *original
	canon := true

	// Apply forks (after Berlin) to the copy.
	if block := override.BerlinBlock; block != nil {
		copy.BerlinBlock = block
		canon = false
	}
	if block := override.LondonBlock; block != nil {
		copy.LondonBlock = block
		canon = false
	}
	if block := override.ArrowGlacierBlock; block != nil {
		copy.ArrowGlacierBlock = block
		canon = false
	}
	if block := override.GrayGlacierBlock; block != nil {
		copy.GrayGlacierBlock = block
		canon = false
	}
	if block := override.MergeNetsplitBlock; block != nil {
		copy.MergeNetsplitBlock = block
		canon = false
	}
	if timestamp := override.ShanghaiTime; timestamp != nil {
		copy.ShanghaiTime = timestamp
		canon = false
	}
	if timestamp := override.CancunTime; timestamp != nil {
		copy.CancunTime = timestamp
		canon = false
	}
	if timestamp := override.PragueTime; timestamp != nil {
		copy.PragueTime = timestamp
		canon = false
	}
	if timestamp := override.VerkleTime; timestamp != nil {
		copy.VerkleTime = timestamp
		canon = false
	}

	return copy, canon
}

func SetupGenesisBlockWithOverride(db ethdb.Database, triedb *triedb.Database, genesis *Genesis, overrides *ChainOverrides) (*params.ChainConfig, common.Hash, error) {
	if genesis != nil && genesis.Config == nil {
		return params.AllEthashProtocolChanges, common.Hash{}, errGenesisNoConfig
	}
	// Just commit the new block if there is no stored genesis block.
	stored := rawdb.ReadCanonicalHash(db, 0)
	if (stored == common.Hash{}) {
		if genesis == nil {
			log.Info("Writing default main-net genesis block")
			genesis = DefaultStableNetMainnetGenesisBlock()
		} else {
			log.Info("Writing custom genesis block")
		}
		applyOverrides(genesis.Config, overrides)

		if err := validateAnzeonGenesisConfig(genesis.Config); err != nil {
			return nil, common.Hash{}, err
		}
		if err := initializeAnzeonGenesis(genesis); err != nil {
			return genesis.Config, common.Hash{}, err
		}
		block, err := genesis.Commit(db, triedb)
		if err != nil {
			return genesis.Config, common.Hash{}, err
		}
		return genesis.Config, block.Hash(), nil
	}
	// The genesis block is present(perhaps in ancient database) while the
	// state database is not initialized yet. It can happen that the node
	// is initialized with an external ancient store. Commit genesis state
	// in this case.
	header := rawdb.ReadHeader(db, stored, 0)
	if header.Root != types.EmptyRootHash && !triedb.Initialized(header.Root) {
		if genesis == nil {
			genesis = DefaultStableNetMainnetGenesisBlock()
		}
		applyOverrides(genesis.Config, overrides)

		if err := validateAnzeonGenesisConfig(genesis.Config); err != nil {
			return nil, common.Hash{}, err
		}
		if err := initializeAnzeonGenesis(genesis); err != nil {
			return genesis.Config, stored, err
		}

		// Ensure the stored genesis matches with the given one.
		hash := genesis.ToBlock().Hash()
		if hash != stored {
			return genesis.Config, hash, &GenesisMismatchError{stored, hash}
		}
		block, err := genesis.Commit(db, triedb)
		if err != nil {
			return genesis.Config, hash, err
		}
		return genesis.Config, block.Hash(), nil
	}
	// Check whether the genesis block is already written.
	if genesis != nil {
		applyOverrides(genesis.Config, overrides)
		if err := validateAnzeonGenesisConfig(genesis.Config); err != nil {
			return nil, common.Hash{}, err
		}
		if err := initializeAnzeonGenesis(genesis); err != nil {
			return genesis.Config, common.Hash{}, err
		}
		hash := genesis.ToBlock().Hash()
		if hash != stored {
			return genesis.Config, hash, &GenesisMismatchError{stored, hash}
		}
	}
	// Get the existing chain configuration.
	newcfg := genesis.configOrDefault(stored)
	applyOverrides(newcfg, overrides)
	if err := newcfg.CheckConfigForkOrder(); err != nil {
		return newcfg, common.Hash{}, err
	}
	storedcfg := rawdb.ReadChainConfig(db, stored)
	if storedcfg == nil {
		log.Warn("Found genesis block without chain config")
		rawdb.WriteChainConfig(db, stored, newcfg)
		return newcfg, stored, nil
	}
	storedData, _ := json.Marshal(storedcfg)
	// Special case: if a private network is being used (no genesis and also no
	// mainnet hash in the database), we must not apply the `configOrDefault`
	// chain config as that would be AllProtocolChanges (applying any new fork
	// on top of an existing private network genesis block). In that case, only
	// apply the overrides.
	if genesis == nil && stored != params.MainnetGenesisHash && stored != params.StableNetMainnetGenesisHash {
		newcfg = storedcfg
		applyOverrides(newcfg, overrides)
	}
	// Check config compatibility and write the config. Compatibility errors
	// are returned to the caller unless we're already at block zero.
	head := rawdb.ReadHeadHeader(db)
	if head == nil {
		return newcfg, stored, errors.New("missing head header")
	}
	compatErr := storedcfg.CheckCompatible(newcfg, head.Number.Uint64(), head.Time)
	if compatErr != nil && ((head.Number.Uint64() != 0 && compatErr.RewindToBlock != 0) || (head.Time != 0 && compatErr.RewindToTime != 0)) {
		return newcfg, stored, compatErr
	}
	// Don't overwrite if the old is identical to the new
	if newData, _ := json.Marshal(newcfg); !bytes.Equal(storedData, newData) {
		rawdb.WriteChainConfig(db, stored, newcfg)
	}
	return newcfg, stored, nil
}

func LoadChainConfigWithOverride(db ethdb.Database, genesis *Genesis, overrides *ChainOverrides) (*params.ChainConfig, error) {
	if genesis != nil && genesis.Config == nil {
		return params.AllEthashProtocolChanges, errGenesisNoConfig
	}

	stored := rawdb.ReadCanonicalHash(db, 0)
	// If no genesis block is stored, use the provided genesis or default
	if (stored == common.Hash{}) {
		if genesis == nil {
			genesis = DefaultStableNetMainnetGenesisBlock()
		}
		if genesis.Config == nil {
			return params.AllEthashProtocolChanges, errGenesisNoConfig
		}
		applyOverrides(genesis.Config, overrides)
		return genesis.Config, nil
	}

	// If a canonical genesis already exists and a genesis is provided, ensure
	// the provided genesis does not point to a different chain.
	if genesis != nil {
		applyOverrides(genesis.Config, overrides)
		if err := validateAnzeonGenesisConfig(genesis.Config); err != nil {
			return nil, err
		}
		if err := initializeAnzeonGenesis(genesis); err != nil {
			return genesis.Config, err
		}
		hash := genesis.ToBlock().Hash()
		if hash != stored {
			return genesis.Config, &GenesisMismatchError{Stored: stored, New: hash}
		}
	}

	// Genesis exists, get the config
	newcfg := genesis.configOrDefault(stored)
	applyOverrides(newcfg, overrides)

	// Validate fork order
	if err := newcfg.CheckConfigForkOrder(); err != nil {
		return newcfg, err
	}

	// Check if there's a stored config in the database
	storedcfg := rawdb.ReadChainConfig(db, stored)
	if storedcfg != nil {
		// Special case: private network - use stored config with overrides
		if genesis == nil && stored != params.MainnetGenesisHash && stored != params.StableNetMainnetGenesisHash {
			newcfg = storedcfg
			applyOverrides(newcfg, overrides)
		}
	}

	return newcfg, nil
}

func validateAnzeonGenesisConfig(config *params.ChainConfig) error {
	if config != nil && config.AnzeonEnabled() {
		if err := config.Anzeon.CheckValidity(); err != nil {
			return fmt.Errorf("Invalid genesis config: %v", err)
		}
	}
	return nil
}

func splitAndTrim(s, sep string) (ret []string) {
	l := strings.Split(s, sep)
	for _, r := range l {
		r = strings.TrimSpace(r)
		if len(r) > 0 {
			ret = append(ret, r)
		}
	}
	return ret
}

// SplitAndTrim splits input separated by a comma
// and trims excessive white space from the substrings.
func SplitAndTrim(input string) (ret []string) {
	l := strings.Split(input, ",")
	for _, r := range l {
		if r = strings.TrimSpace(r); r != "" {
			ret = append(ret, r)
		}
	}
	return ret
}

// ParseNetlist parses a comma-separated list of CIDR masks.
// Whitespace and extra commas are ignored.
func ParseNetlist(s string) (*Netlist, error) {
	ws := strings.NewReplacer(" ", "", "\n", "", "\t", "")
	masks := strings.Split(ws.Replace(s), ",")
	l := make(Netlist, 0)
	for _, mask := range masks {
		if mask == "" {
			continue
		}
		_, n, err := net.ParseCIDR(mask)
		if err != nil {
			return nil, err
		}
		l = append(l, *n)
	}
	return &l, nil
}

func prune(snaptree *snapshot.Tree, root common.Hash, maindb ethdb.Database, stateBloom *stateBloom, bloomPath string, middleStateRoots map[common.Hash]struct{}, start time.Time) error {
	// Delete all stale trie nodes in the disk. With the help of state bloom
	// the trie nodes(and codes) belong to the active state will be filtered
	// out. A very small part of stale tries will also be filtered because of
	// the false-positive rate of bloom filter. But the assumption is held here
	// that the false-positive is low enough(~0.05%). The probability of the
	// dangling node is the state root is super low. So the dangling nodes in
	// theory will never ever be visited again.
	var (
		skipped, count int
		size           common.StorageSize
		pstart         = time.Now()
		logged         = time.Now()
		batch          = maindb.NewBatch()
		iter           = maindb.NewIterator(nil, nil)
	)
	for iter.Next() {
		key := iter.Key()

		// All state entries don't belong to specific state and genesis are deleted here
		// - trie node
		// - legacy contract code
		// - new-scheme contract code
		isCode, codeKey := rawdb.IsCodeKey(key)
		if len(key) == common.HashLength || isCode {
			checkKey := key
			if isCode {
				checkKey = codeKey
			}
			if _, exist := middleStateRoots[common.BytesToHash(checkKey)]; exist {
				log.Debug("Forcibly delete the middle state roots", "hash", common.BytesToHash(checkKey))
			} else {
				if stateBloom.Contain(checkKey) {
					skipped += 1
					continue
				}
			}
			count += 1
			size += common.StorageSize(len(key) + len(iter.Value()))
			batch.Delete(key)

			var eta time.Duration // Realistically will never remain uninited
			if done := binary.BigEndian.Uint64(key[:8]); done > 0 {
				var (
					left  = math.MaxUint64 - binary.BigEndian.Uint64(key[:8])
					speed = done/uint64(time.Since(pstart)/time.Millisecond+1) + 1 // +1s to avoid division by zero
				)
				eta = time.Duration(left/speed) * time.Millisecond
			}
			if time.Since(logged) > 8*time.Second {
				log.Info("Pruning state data", "nodes", count, "skipped", skipped, "size", size,
					"elapsed", common.PrettyDuration(time.Since(pstart)), "eta", common.PrettyDuration(eta))
				logged = time.Now()
			}
			// Recreate the iterator after every batch commit in order
			// to allow the underlying compactor to delete the entries.
			if batch.ValueSize() >= ethdb.IdealBatchSize {
				batch.Write()
				batch.Reset()

				iter.Release()
				iter = maindb.NewIterator(nil, key)
			}
		}
	}
	if batch.ValueSize() > 0 {
		batch.Write()
		batch.Reset()
	}
	iter.Release()
	log.Info("Pruned state data", "nodes", count, "size", size, "elapsed", common.PrettyDuration(time.Since(pstart)))

	// Pruning is done, now drop the "useless" layers from the snapshot.
	// Firstly, flushing the target layer into the disk. After that all
	// diff layers below the target will all be merged into the disk.
	if err := snaptree.Cap(root, 0); err != nil {
		return err
	}
	// Secondly, flushing the snapshot journal into the disk. All diff
	// layers upon are dropped silently. Eventually the entire snapshot
	// tree is converted into a single disk layer with the pruning target
	// as the root.
	if _, err := snaptree.Journal(root); err != nil {
		return err
	}
	// Delete the state bloom, it marks the entire pruning procedure is
	// finished. If any crashes or manual exit happens before this,
	// `RecoverPruning` will pick it up in the next restarts to redo all
	// the things.
	os.RemoveAll(bloomPath)

	// Start compactions, will remove the deleted data from the disk immediately.
	// Note for small pruning, the compaction is skipped.
	if count >= rangeCompactionThreshold {
		cstart := time.Now()
		for b := 0x00; b <= 0xf0; b += 0x10 {
			var (
				start = []byte{byte(b)}
				end   = []byte{byte(b + 0x10)}
			)
			if b == 0xf0 {
				end = nil
			}
			log.Info("Compacting database", "range", fmt.Sprintf("%#x-%#x", start, end), "elapsed", common.PrettyDuration(time.Since(cstart)))
			if err := maindb.Compact(start, end); err != nil {
				log.Error("Database compaction failed", "error", err)
				return err
			}
		}
		log.Info("Database compaction finished", "elapsed", common.PrettyDuration(time.Since(cstart)))
	}
	log.Info("State pruning successful", "pruned", size, "elapsed", common.PrettyDuration(time.Since(start)))
	return nil
}

// extractGenesis loads the genesis state and commits all the state entries
// into the given bloomfilter.
func extractGenesis(db ethdb.Database, stateBloom *stateBloom) error {
	genesisHash := rawdb.ReadCanonicalHash(db, 0)
	if genesisHash == (common.Hash{}) {
		return errors.New("missing genesis hash")
	}
	genesis := rawdb.ReadBlock(db, genesisHash, 0)
	if genesis == nil {
		return errors.New("missing genesis block")
	}
	t, err := trie.NewStateTrie(trie.StateTrieID(genesis.Root()), triedb.NewDatabase(db, triedb.HashDefaults))
	if err != nil {
		return err
	}
	accIter, err := t.NodeIterator(nil)
	if err != nil {
		return err
	}
	for accIter.Next(true) {
		hash := accIter.Hash()

		// Embedded nodes don't have hash.
		if hash != (common.Hash{}) {
			stateBloom.Put(hash.Bytes(), nil)
		}
		// If it's a leaf node, yes we are touching an account,
		// dig into the storage trie further.
		if accIter.Leaf() {
			var acc types.StateAccount
			if err := rlp.DecodeBytes(accIter.LeafBlob(), &acc); err != nil {
				return err
			}
			if acc.Root != types.EmptyRootHash {
				id := trie.StorageTrieID(genesis.Root(), common.BytesToHash(accIter.LeafKey()), acc.Root)
				storageTrie, err := trie.NewStateTrie(id, triedb.NewDatabase(db, triedb.HashDefaults))
				if err != nil {
					return err
				}
				storageIter, err := storageTrie.NodeIterator(nil)
				if err != nil {
					return err
				}
				for storageIter.Next(true) {
					hash := storageIter.Hash()
					if hash != (common.Hash{}) {
						stateBloom.Put(hash.Bytes(), nil)
					}
				}
				if storageIter.Error() != nil {
					return storageIter.Error()
				}
			}
			if !bytes.Equal(acc.CodeHash, types.EmptyCodeHash.Bytes()) {
				stateBloom.Put(acc.CodeHash, nil)
			}
		}
	}
	return accIter.Error()
}

// Prune deletes all historical state nodes except the nodes belong to the
// specified state version. If user doesn't specify the state version, use
// the bottom-most snapshot diff layer as the target.
func (p *Pruner) Prune(root common.Hash) error {
	// If the state bloom filter is already committed previously,
	// reuse it for pruning instead of generating a new one. It's
	// mandatory because a part of state may already be deleted,
	// the recovery procedure is necessary.
	_, stateBloomRoot, err := findBloomFilter(p.config.Datadir)
	if err != nil {
		return err
	}
	if stateBloomRoot != (common.Hash{}) {
		return RecoverPruning(p.config.Datadir, p.db)
	}
	// If the target state root is not specified, use the HEAD-127 as the
	// target. The reason for picking it is:
	// - in most of the normal cases, the related state is available
	// - the probability of this layer being reorg is very low
	var layers []snapshot.Snapshot
	if root == (common.Hash{}) {
		// Retrieve all snapshot layers from the current HEAD.
		// In theory there are 128 difflayers + 1 disk layer present,
		// so 128 diff layers are expected to be returned.
		layers = p.snaptree.Snapshots(p.chainHeader.Root, 128, true)
		if len(layers) != 128 {
			// Reject if the accumulated diff layers are less than 128. It
			// means in most of normal cases, there is no associated state
			// with bottom-most diff layer.
			return fmt.Errorf("snapshot not old enough yet: need %d more blocks", 128-len(layers))
		}
		// Use the bottom-most diff layer as the target
		root = layers[len(layers)-1].Root()
	}
	// Ensure the root is really present. The weak assumption
	// is the presence of root can indicate the presence of the
	// entire trie.
	if !rawdb.HasLegacyTrieNode(p.db, root) {
		// The special case is for clique based networks(goerli
		// and some other private networks), it's possible that two
		// consecutive blocks will have same root. In this case snapshot
		// difflayer won't be created. So HEAD-127 may not paired with
		// head-127 layer. Instead the paired layer is higher than the
		// bottom-most diff layer. Try to find the bottom-most snapshot
		// layer with state available.
		//
		// Note HEAD and HEAD-1 is ignored. Usually there is the associated
		// state available, but we don't want to use the topmost state
		// as the pruning target.
		var found bool
		for i := len(layers) - 2; i >= 2; i-- {
			if rawdb.HasLegacyTrieNode(p.db, layers[i].Root()) {
				root = layers[i].Root()
				found = true
				log.Info("Selecting middle-layer as the pruning target", "root", root, "depth", i)
				break
			}
		}
		if !found {
			if len(layers) > 0 {
				return errors.New("no snapshot paired state")
			}
			return fmt.Errorf("associated state[%x] is not present", root)
		}
	} else {
		if len(layers) > 0 {
			log.Info("Selecting bottom-most difflayer as the pruning target", "root", root, "height", p.chainHeader.Number.Uint64()-127)
		} else {
			log.Info("Selecting user-specified state as the pruning target", "root", root)
		}
	}
	// All the state roots of the middle layer should be forcibly pruned,
	// otherwise the dangling state will be left.
	middleRoots := make(map[common.Hash]struct{})
	for _, layer := range layers {
		if layer.Root() == root {
			break
		}
		middleRoots[layer.Root()] = struct{}{}
	}
	// Traverse the target state, re-construct the whole state trie and
	// commit to the given bloom filter.
	start := time.Now()
	if err := snapshot.GenerateTrie(p.snaptree, root, p.db, p.stateBloom); err != nil {
		return err
	}
	// Traverse the genesis, put all genesis state entries into the
	// bloom filter too.
	if err := extractGenesis(p.db, p.stateBloom); err != nil {
		return err
	}
	filterName := bloomFilterName(p.config.Datadir, root)

	log.Info("Writing state bloom to disk", "name", filterName)
	if err := p.stateBloom.Commit(filterName, filterName+stateBloomFileTempSuffix); err != nil {
		return err
	}
	log.Info("State bloom filter committed", "name", filterName)
	return prune(p.snaptree, root, p.db, p.stateBloom, filterName, middleRoots, start)
}

func SplitAndTrim(input string) (ret []string) {
	l := strings.Split(input, ",")
	for _, r := range l {
		if r = strings.TrimSpace(r); r != "" {
			ret = append(ret, r)
		}
	}
	return ret
}

// IntermediateRoot computes the current root hash of the state trie.
// It is called in between transactions to get the root hash that
// goes into transaction receipts.
func (s *StateDB) IntermediateRoot(deleteEmptyObjects bool) common.Hash {
	// Finalise all the dirty storage states and write them into the tries
	s.Finalise(deleteEmptyObjects)

	// If there was a trie prefetcher operating, it gets aborted and irrevocably
	// modified after we start retrieving tries. Remove it from the statedb after
	// this round of use.
	//
	// This is weird pre-byzantium since the first tx runs with a prefetcher and
	// the remainder without, but pre-byzantium even the initial prefetcher is
	// useless, so no sleep lost.
	prefetcher := s.prefetcher
	if s.prefetcher != nil {
		defer func() {
			s.prefetcher.close()
			s.prefetcher = nil
		}()
	}
	// Although naively it makes sense to retrieve the account trie and then do
	// the contract storage and account updates sequentially, that short circuits
	// the account prefetcher. Instead, let's process all the storage updates
	// first, giving the account prefetches just a few more milliseconds of time
	// to pull useful data from disk.
	for addr := range s.stateObjectsPending {
		if obj := s.stateObjects[addr]; !obj.deleted {
			obj.updateRoot()
		}
	}
	// Now we're about to start to write changes to the trie. The trie is so far
	// _untouched_. We can check with the prefetcher, if it can give us a trie
	// which has the same root, but also has some content loaded into it.
	if prefetcher != nil {
		if trie := prefetcher.trie(common.Hash{}, s.originalRoot); trie != nil {
			s.trie = trie
		}
	}
	usedAddrs := make([][]byte, 0, len(s.stateObjectsPending))
	for addr := range s.stateObjectsPending {
		if obj := s.stateObjects[addr]; obj.deleted {
			s.deleteStateObject(obj)
			s.AccountDeleted += 1
		} else {
			s.updateStateObject(obj)
			s.AccountUpdated += 1
		}
		usedAddrs = append(usedAddrs, common.CopyBytes(addr[:])) // Copy needed for closure
	}
	if prefetcher != nil {
		prefetcher.used(common.Hash{}, s.originalRoot, usedAddrs)
	}
	if len(s.stateObjectsPending) > 0 {
		s.stateObjectsPending = make(map[common.Address]struct{})
	}
	// Track the amount of time wasted on hashing the account trie
	defer func(start time.Time) { s.AccountHashes += time.Since(start) }(time.Now())

	return s.trie.Hash()
}

// newRetrySendingRoundChangeTimer sets a retry timer to reattempt round-change after a timeout.
// It copies round (and seq for config) under currentMutex; the callback uses only that copied round and never reads c.current.
func (c *Core) newRetrySendingRoundChangeTimer() {
	// Snapshot current view under lock to avoid races with startNewRound/updateRoundState.
	var seq, round *big.Int
	c.currentMutex.RLock()
	if c.current != nil {
		seq = new(big.Int).Set(c.current.Sequence())
		round = new(big.Int).Set(c.current.Round())
	}
	c.currentMutex.RUnlock()
	if seq == nil || round == nil {
		return
	}

	cfg := c.config.GetConfig(seq)
	timeout := time.Duration(cfg.RequestTimeout) * time.Millisecond

	c.logger.Trace("WBFT: set ROUND-CHANGE retry timer", "round", round.Uint64(), "timeout", timeout.Seconds())

	c.timerMu.Lock()
	c.stopRetrySendingRoundChangeTimer()
	c.retrySendingRoundChangeTimer = time.AfterFunc(timeout, func() {
		c.sendEvent(retryTimeoutEvent{round})
	})
	c.timerMu.Unlock()
}

func (d Duration) Duration() time.Duration {
	return time.Duration(d)
}

func (c Config) GetConfig(blockNumber *big.Int) Config {
	newConfig := c
	if c.Transitions != nil {
		c.getTransitionValue(blockNumber, func(transition params.Transition) {
			if transition.RequestTimeoutSeconds != 0 {
				// RequestTimeout is on milliseconds
				newConfig.RequestTimeout = transition.RequestTimeoutSeconds * 1000
			}
			if transition.BlockPeriodSeconds != 0 {
				newConfig.BlockPeriod = transition.BlockPeriodSeconds
			}
			if transition.EpochLength != 0 {
				newConfig.Epoch = transition.EpochLength
			}
			if transition.ProposerPolicy != nil {
				newConfig.ProposerPolicy = NewProposerPolicy(ProposerPolicyId(*transition.ProposerPolicy))
			}
			if transition.MaxRequestTimeoutSeconds != nil {
				newConfig.MaxRequestTimeoutSeconds = *transition.MaxRequestTimeoutSeconds
			}
		})
	}
	return newConfig
}

func (c *Core) stopRetrySendingRoundChangeTimer() {
	if c.retrySendingRoundChangeTimer != nil {
		c.retrySendingRoundChangeTimer.Stop()
	}
}

// broadcastNextRoundChange sends the ROUND CHANGE message with current round + 1
func (c *Core) broadcastNextRoundChange() {
	cv := c.currentView()
	c.broadcastRoundChange(new(big.Int).Add(cv.Round, common.Big1))
}

// It
// - Creates and sign ROUND-CHANGE message
// - broadcast the ROUND-CHANGE message with the given round
func (c *Core) broadcastRoundChange(round *big.Int) {
	c.newRetrySendingRoundChangeTimer()
	logger := c.currentLogger(true, nil)

	// Validates new round corresponds to current view
	cv := c.currentView()
	if cv.Round.Cmp(round) > 0 {
		logger.Warn("WBFT: invalid past target round", "current", cv.Round, "target", round)
		return
	}

	roundChange := wbfmessage.NewRoundChange(c.current.Sequence(), round, c.current.preparedRound, c.current.preparedBlock)

	// Sign message
	encodedPayload, err := roundChange.EncodePayloadForSigning()
	if err != nil {
		withMsg(logger, roundChange).Error("WBFT: failed to encode ROUND-CHANGE message", "err", err)
		return
	}
	signature, err := c.backend.Sign(encodedPayload)
	if err != nil {
		withMsg(logger, roundChange).Error("WBFT: failed to sign ROUND-CHANGE message", "err", err)
		return
	}
	roundChange.SetSignature(signature)

	// Extend ROUND-CHANGE message with PREPARE justification
	if c.WBFTPreparedPrepares != nil {
		roundChange.Justification = c.WBFTPreparedPrepares
		withMsg(logger, roundChange).Debug("WBFT: extended ROUND-CHANGE message with PREPARE justification", "justification", roundChange.Justification)
	}

	// RLP-encode message
	data, err := rlp.EncodeToBytes(roundChange)
	if err != nil {
		withMsg(logger, roundChange).Error("WBFT: failed to encode ROUND-CHANGE message", "err", err)
		return
	}

	withMsg(logger, roundChange).Info("WBFT: broadcast ROUND-CHANGE message", "payload", hexutil.Encode(data))

	// Broadcast RLP-encoded message
	if err = c.backend.Broadcast(c.valSet, roundChange.Code(), data); err != nil {
		withMsg(logger, roundChange).Error("WBFT: failed to broadcast ROUND-CHANGE message", "err", err)
		return
	}
}

// higherRoundMessages returns the count of validators we received a ROUND-CHANGE message from
// for any round greater than the given round
func (rcs *roundChangeSet) higherRoundMessages(round *big.Int) int {
	rcs.mu.Lock()
	defer rcs.mu.Unlock()

	addresses := make(map[common.Address]struct{})
	for k, rms := range rcs.roundChanges {
		if k > round.Uint64() {
			for addr := range rms.messages {
				addresses[addr] = struct{}{}
			}
		}
	}
	return len(addresses)
}

func newRoundChangeSet(valSet wbft.ValidatorSet) *roundChangeSet {
	return &roundChangeSet{
		validatorSet:         valSet,
		roundChanges:         make(map[uint64]*wbftMsgSet),
		prepareMessages:      make(map[uint64][]*wbfmessage.Prepare),
		highestPreparedRound: make(map[uint64]*big.Int),
		highestPreparedBlock: make(map[uint64]wbft.Proposal),
		mu:                   new(sync.Mutex),
	}
}

// startNewRound starts a new round. if round equals to 0, it means to starts a new sequence
func (c *Core) startNewRound(round *big.Int) {
	c.currentMutex.Lock()
	defer c.currentMutex.Unlock()

	var logger log.Logger
	if c.current == nil {
		logger = c.logger.New("old.round", -1, "old.seq", 0)
	} else {
		logger = c.currentLogger(false, nil)
	}
	logger = logger.New("target.round", round)

	roundChange := false

	// Try to get last proposal
	lastProposal, lastProposer := c.backend.LastProposal()
	if lastProposal != nil {
		logger = logger.New("lastProposal.number", lastProposal.Number().Uint64(), "lastProposal.hash", lastProposal.Hash())
	}

	logger.Debug("WBFT: initialize new round")

	if c.current == nil {
		logger.Debug("WBFT: start at the initial round")
	} else if lastProposal.Number().Cmp(c.current.Sequence()) >= 0 {
		diff := new(big.Int).Sub(lastProposal.Number(), c.current.Sequence())
		sequenceMeter.Mark(new(big.Int).Add(diff, common.Big1).Int64())

		if !c.consensusTimestamp.IsZero() {
			consensusTimer.UpdateSince(c.consensusTimestamp)
			c.consensusTimestamp = time.Time{}
		}
		logger.Debug("WBFT: catch up last block proposal")
	} else if lastProposal.Number().Cmp(big.NewInt(c.current.Sequence().Int64()-1)) == 0 {
		if round.Cmp(common.Big0) == 0 {
			// same seq and round, don't need to start new round
			logger.Debug("WBFT: same round, no need to start new round")
			return
		} else if round.Cmp(c.current.Round()) < 0 {
			logger.Warn("WBFT: next round is inferior to current round")
			return
		}
		roundChange = true
	} else {
		logger.Warn("WBFT: next sequence is before last block proposal")
		return
	}

	var oldLogger log.Logger
	if c.current == nil {
		oldLogger = c.logger.New("old.round", -1, "old.seq", 0)
	} else {
		oldLogger = c.logger.New("old.round", c.current.Round().Uint64(), "old.sequence", c.current.Sequence().Uint64(), "old.state", c.state.String(), "old.proposer", c.valSet.GetProposer())
	}

	if c.current != nil && round.Cmp(c.current.Round()) > 0 {
		roundMeter.Mark(new(big.Int).Sub(round, c.current.Round()).Int64())
	}

	// Create next view
	var newView *wbft.View
	var nextValSet wbft.ValidatorSet
	if roundChange {
		newView = &wbft.View{
			Sequence: new(big.Int).Set(c.current.Sequence()),
			Round:    new(big.Int).Set(round),
		}
		nextValSet = c.valSet
	} else {
		newView = &wbft.View{
			Sequence: new(big.Int).Add(lastProposal.Number(), common.Big1),
			Round:    new(big.Int),
		}
		nextValSet = c.backend.Validators(lastProposal)

		// Add extra seal that contributed to consensus
		c.addEffectiveSealToExtraSeal()
	}

	// New snapshot for new round
	c.updateRoundState(nextValSet, newView, roundChange)

	// Calculate new proposer
	c.valSet.CalcProposer(lastProposer, newView.Round.Uint64())
	c.setState(StateAcceptRequest)

	// Update RoundChangeSet by deleting older round messages
	if round.Uint64() == 0 {
		c.WBFTPreparedPrepares = nil
		c.roundChangeSet = newRoundChangeSet(c.valSet)
		c.ClearExtraSeals(lastProposal.Number())
	} else {
		// Clear earlier round messages
		c.roundChangeSet.ClearLowerThan(round)
	}
	c.roundChangeSet.NewRound(round)

	c.backend.NotifyNewRound(round)

	// the order of NotifyNewRound() and newRoundChangeTimer() does not matter on actual consensus, but
	// it matters on multi-engine test, so we keep the order as it is
	c.newRoundChangeTimer()

	oldLogger.Info("WBFT: start new round", "next.round", newView.Round, "next.seq", newView.Sequence, "next.proposer", c.valSet.GetProposer(), "next.valSet", c.valSet.List(), "next.size", c.valSet.Size(), "next.IsProposer", c.IsProposer())
}

func (m *RoundChange) DecodeRLP(stream *rlp.Stream) error {
	var err error

	// RoundChange Message
	if _, err = stream.List(); err != nil {
		return err
	}

	// Signed Payload
	if _, err = stream.List(); err != nil {
		log.Error("WBFT: Error List() Signed Payload", "err", err)
		return err
	}

	// Payload
	encodedPayload, err := stream.Raw()
	if err != nil {
		log.Error("WBFT: Error Raw()", "err", err)
		return err
	}

	payloadStream := rlp.NewStream(bytes.NewReader(encodedPayload), 0)

	if _, err = payloadStream.List(); err != nil {
		log.Error("WBFT: Error List() Payload", "err", err)
		return err
	}

	if err = payloadStream.Decode(&m.Sequence); err != nil {
		log.Error("WBFT: Error Decode(&m.Sequence)", "err", err)
		return err
	}
	if err = payloadStream.Decode(&m.Round); err != nil {
		log.Error("WBFT: Error Decode(&m.Round)", "err", err)
		return err
	}

	// Prepared
	var size uint64
	if size, err = payloadStream.List(); err != nil {
		log.Error("WBFT: Error List() Prepared", "err", err)
		return err
	}
	if size > 0 {
		if err = payloadStream.Decode(&m.PreparedRound); err != nil {
			log.Error("WBFT: Error Decode(&m.PreparedRound)", "err", err)
			return err
		}
		if err = payloadStream.Decode(&m.PreparedDigest); err != nil {
			log.Error("WBFT: Error Decode(&m.PreparedDigest)", "err", err)
			return err
		}
	}
	// End Prepared
	if err = payloadStream.ListEnd(); err != nil {
		return err
	}

	// End Payload
	if err = payloadStream.ListEnd(); err != nil {
		return err
	}

	if err = stream.Decode(&m.signature); err != nil {
		return err
	}
	// End SignedPayload
	if err = stream.ListEnd(); err != nil {
		return err
	}

	if _, size, err = stream.Kind(); err != nil {
		log.Error("WBFT: Error Kind()", "err", err)
		return err
	}
	if size == 0 {
		if _, err = stream.Raw(); err != nil {
			log.Error("WBFT: Error Raw()", "err", err)
			return err
		}
	} else {
		if err = stream.Decode(&m.PreparedBlock); err != nil {
			log.Error("WBFT: Error Decode(&m.PreparedDigest)", "err", err)
			return err
		}
		if m.PreparedBlock.Hash() != m.PreparedDigest {
			log.Error("WBFT: Error m.PreparedDigest.Hash() != digest", "m.hash", m.PreparedBlock.Hash(), "m.digest", m.PreparedDigest)
			return wbftcommon.ErrFailedDecodePreprepare
		}
	}

	if _, size, err = stream.Kind(); err != nil {
		log.Error("WBFT: Error Kind()", "err", err)
		return err
	}
	if size == 0 {
		if _, err = stream.Raw(); err != nil {
			log.Error("WBFT: Error Raw()", "err", err)
			return err
		}
	} else {
		if err = stream.Decode(&m.Justification); err != nil {
			log.Error("WBFT: Error Decode(&m.Justification)", "err", err)
			return err
		}
	}

	// End RoundChange Message
	if err = stream.ListEnd(); err != nil {
		return err
	}

	m.code = RoundChangeCode

	return nil
}

// Add adds the round and message into round change set
func (rcs *roundChangeSet) Add(r *big.Int, msg wbfmessage.WBFTMessage, preparedRound *big.Int, preparedBlock wbft.Proposal, prepareMessages []*wbfmessage.Prepare, quorumSize int) error {
	rcs.mu.Lock()
	defer rcs.mu.Unlock()

	round := r.Uint64()
	if rcs.roundChanges[round] == nil {
		rcs.roundChanges[round] = newWBFTMsgSet(rcs.validatorSet)
	}
	if err := rcs.roundChanges[round].Add(msg); err != nil {
		return err
	}

	if preparedRound != nil && (rcs.highestPreparedRound[round] == nil || preparedRound.Cmp(rcs.highestPreparedRound[round]) > 0) {
		roundChange := msg.(*wbfmessage.RoundChange)
		if hasMatchingRoundChangeAndPrepares(roundChange, prepareMessages, quorumSize) == nil {
			rcs.highestPreparedRound[round] = preparedRound
			rcs.highestPreparedBlock[round] = preparedBlock
			rcs.prepareMessages[round] = prepareMessages
		}
	}

	return nil
}

func (c *Core) currentView() *wbft.View {
	return &wbft.View{
		Sequence: new(big.Int).Set(c.current.Sequence()),
		Round:    new(big.Int).Set(c.current.Round()),
	}
}

// commitWBFT is called once quorum of commits is reached
// - computes committedSeals from each received commit messages
// - then commits block proposal to database with committed seals
// - broadcast round change
func (c *Core) commitWBFT() {
	c.setState(StateCommitted)

	proposal := c.current.Proposal()
	if proposal != nil {
		// Compute prepared seals
		preparedSeals := make([]wbft.SealData, c.current.WBFTPrepares.Size())
		for i, msg := range c.current.WBFTPrepares.Values() {
			idx, _ := c.valSet.GetByAddress(msg.Source())
			if idx < 0 {
				continue
			}
			preparedSeals[i] = wbft.SealData{
				Sealer: uint32(idx),
				Seal:   make([]byte, types.IstanbulExtraSeal),
			}
			prepareMsg := msg.(*wbfmessage.Prepare)
			copy(preparedSeals[i].Seal[:], prepareMsg.PrepareSeal[:])
		}

		// Compute committed seals
		committedSeals := make([]wbft.SealData, c.current.WBFTCommits.Size())
		for i, msg := range c.current.WBFTCommits.Values() {
			idx, _ := c.valSet.GetByAddress(msg.Source())
			if idx < 0 {
				continue
			}
			committedSeals[i] = wbft.SealData{
				Sealer: uint32(idx),
				Seal:   make([]byte, types.IstanbulExtraSeal),
			}
			commitMsg := msg.(*wbfmessage.Commit)
			copy(committedSeals[i].Seal[:], commitMsg.CommitSeal[:])
		}

		// Commit proposal to database
		if err := c.backend.Commit(proposal, preparedSeals, committedSeals, c.currentView().Round); err != nil {
			c.currentLogger(true, nil).Error("WBFT: error committing proposal", "err", err)
			c.broadcastNextRoundChange()
			return
		}
	}
}

// Commit seals a block and moves the chain forward to a new empty block.
func (n *WBFTBackend) Commit() common.Hash {
	return n.eth.Miner().CommitSimulated()
}

func (beacon *Beacon) Finalize(chain consensus.ChainHeaderReader, header *types.Header, state *state.StateDB, txs []*types.Transaction, uncles []*types.Header, withdrawals []*types.Withdrawal) error {
	if !beacon.IsPoSHeader(header) {
		beacon.ethone.Finalize(chain, header, state, txs, uncles, nil)
		return nil
	}
	// Withdrawals processing.
	for _, w := range withdrawals {
		// Convert amount from gwei to wei.
		amount := new(uint256.Int).SetUint64(w.Amount)
		amount = amount.Mul(amount, uint256.NewInt(params.GWei))
		state.AddBalance(w.Address, amount)
	}
	// No block reward which is issued by consensus layer instead.

	return nil
}

// writeCommittedSeals writes the extra-data field of a block header with given committed seals.
func writeCommittedSeals(committedSeals []wbft.SealData) ApplyWBFTExtra {
	return func(wbftExtra *types.WBFTExtra) error {
		if len(committedSeals) == 0 {
			return wbftcommon.ErrInvalidCommittedSeals
		}
		aggregatedSeal, err := aggregateSeal(committedSeals)
		if err != nil {
			return err
		}
		wbftExtra.CommittedSeal = aggregatedSeal
		return nil
	}
}

