type ValidatorSet interface {
	// Calculate the proposer
	CalcProposer(lastProposer common.Address, round uint64)
	// Return the validator size
	Size() int
	// Return the validator array
	List() []Validator
	// Return the validator address array
	AddressList() []common.Address
	// Get validator by index
	GetByIndex(i uint64) Validator
	// Get validator by given address
	GetByAddress(addr common.Address) (int, Validator)
	// Get current proposer
	GetProposer() Validator
	// Check whether the validator with given address is a proposer
	IsProposer(address common.Address) bool
	// Add validator
	AddValidator(address common.Address, blsPublicKey []byte) bool
	// Remove validator
	RemoveValidator(address common.Address) bool
	// Copy validator set
	Copy() ValidatorSet
	// Get the maximum number of faulty nodes
	F() float64
	// Get quorum size ( which is n-f)
	QuorumSize() int
	// Get proposer policy
	Policy() ProposerPolicy
}

// GetValidators retrieve the validator list of the epoch to which block of given number belongs.
// If the given block is an epoch block, it returns the validators of prior epoch.
// `parents` is a hint for backward traverse.
// exceptional case: blockNumber is genesis block number, then
// it returns the validators from chain config.
func (e *Engine) GetValidators(chain consensus.ChainHeaderReader, blockNumber *big.Int, parentHash common.Hash, parents []*types.Header) (wbft.ValidatorSet, error) {
	chainConfig := chain.Config()

	var (
		epochInfo *types.EpochInfo
		err       error
	)
	if blockNumber.Sign() == 0 {
		// if it is genesis block, get validators from anzeon config
		vs := validator.NewSet(chainConfig.Anzeon.Init.Validators, chainConfig.Anzeon.GetInitialBLSPublicKeys(), e.cfg.ProposerPolicy)
		return vs, nil
	}

	_, epochInfo, err = e.getEpochInfo(chain, blockNumber, parentHash, parents)
	if err != nil {
		return nil, err
	}

	vs := validator.NewSet(epochInfo.GetValidators(), epochInfo.BLSPublicKeys, e.cfg.GetConfig(blockNumber).ProposerPolicy)
	return vs, nil
}

// ProposerPolicy represents the Validator Proposer Policy
type ProposerPolicy struct {
	Id ProposerPolicyId    // Could be RoundRobin or Sticky
	By ValidatorSortByFunc // func that defines how the ValidatorSet should be sorted
}

// Use sets the ValidatorSortByFunc for the given ProposerPolicy and sorts the validatorSets according to it
func (p *ProposerPolicy) Use(v ValidatorSortByFunc) {
	p.By = v
}

type backlogEvent struct {
	src wbft.Validator
	msg wbfmessage.WBFTMessage
}

// isTooFarFutureMessage filters out messages too far ahead in sequence or round
// This function prevents the node from processing messages that are excessively ahead,
// which could disrupt the normal flow of the consensus process
func (c *Core) isTooFarFutureMessage(view *wbft.View) bool {
	curr := c.currentView()

	if view.Sequence.Cmp(curr.Sequence) > 0 {
		// In the initial phase of block consensus, a message with a sequence number one higher than the current sequence may be received.
		if seqDiff, tooFar := c.isSequenceTooFarAhead(view.Sequence, curr.Sequence, sequenceThreshold); tooFar {
			c.logger.Trace("WBFT: future message too far ahead in sequence, dropped",
				"msg_seq", view.Sequence.String(),
				"curr_seq", curr.Sequence.String(),
				"diff", seqDiff.String(),
			)
			return true
		}
	}

	if view.Sequence.Cmp(curr.Sequence) == 0 && view.Round.Cmp(curr.Round) > 0 {
		if roundDiff, tooFar := c.isRoundTooFarAhead(view.Round, curr.Round, roundThreshold); tooFar {
			c.logger.Trace("WBFT: future message too far ahead in round, dropped",
				"msg_round", view.Round.String(),
				"curr_round", curr.Round.String(),
				"diff", roundDiff.String(),
			)
			return true
		}
	}

	return false
}

// it adds the message to backlog which is read on every state change
func (c *Core) addToBacklog(msg wbfmessage.WBFTMessage) {
	logger := c.currentLogger(true, msg)

	src := msg.Source()
	if src == c.Address() {
		logger.Warn("WBFT: backlog from self")
		return
	}

	logger.Trace("WBFT: new backlog message", "backlogs_size", len(c.backlogs))

	c.backlogsMu.Lock()
	defer c.backlogsMu.Unlock()

	backlog := c.backlogs[src]
	if backlog == nil {
		backlog = prque.New[int64, wbfmessage.WBFTMessage](nil)
		c.backlogs[src] = backlog
	}
	view := msg.View()
	backlog.Push(msg, toNegatePriority(msg.Code(), &view))
}

// return errInvalidMessage if the message is invalid
// return errFutureMessage if the message view is larger than current view
// return errOldMessage if the message view is smaller than current view
func (c *Core) checkMessage(msgCode uint64, view *wbft.View) error {
	if view == nil || view.Sequence == nil || view.Round == nil {
		return errInvalidMessage
	}

	// Drop the message if the view's sequence or round number is too far ahead
	// This prevents processing of messages that may disrupt consensus due to excessive lead
	if c.isTooFarFutureMessage(view) {
		return errFutureViewTooFar
	}

	if msgCode == wbfmessage.RoundChangeCode {
		// if ROUND-CHANGE message
		// check that
		// - sequence matches our current sequence
		// - round is in the future
		if view.Sequence.Cmp(c.currentView().Sequence) > 0 {
			return errFutureMessage
		} else if view.Cmp(c.currentView()) < 0 {
			return errOldMessage
		}
		return nil
	}

	// If not ROUND-CHANGE
	// check that round and sequence equals our current round and sequence
	if view.Cmp(c.currentView()) > 0 {
		return errFutureMessage
	}

	if view.Cmp(c.currentView()) < 0 {
		// save prepare and commit message to extraSeal under below condition
		// 1. view's sequence is right before current.Sequence &&
		// 2. view's round is same as prior round &&
		// 3. c.state is AcceptRequest
		if new(big.Int).Sub(c.currentView().Sequence, view.Sequence).Cmp(common.Big1) == 0 && view.Round.Cmp(c.PriorRound()) == 0 && c.state == StateAcceptRequest {
			return errExtraSealMessage
		}
		return errOldMessage
	}

	switch c.state {
	case StateAcceptRequest:
		// StateAcceptRequest only accepts msgPreprepare and msgRoundChange
		// other messages are future messages
		if msgCode > wbfmessage.PreprepareCode {
			return errFutureMessage
		}
		return nil
	case StatePreprepared:
		// StatePreprepared only accepts msgPrepare and msgRoundChange
		// message less than msgPrepare are invalid and greater are future messages
		if msgCode < wbfmessage.PrepareCode {
			return errInvalidMessage
		} else if msgCode > wbfmessage.PrepareCode {
			return errFutureMessage
		}
		return nil
	case StatePrepared:
		// StatePrepared only accepts msgCommit and msgRoundChange
		// other messages are invalid messages
		if msgCode == wbfmessage.PrepareCode {
			return errExtraSealMessage
		} else if msgCode < wbfmessage.CommitCode {
			return errInvalidMessage
		}
		return nil
	case StateCommitted:
		// for prepare, commit message with same view as current
		// return err extraSealMessage
		if msgCode >= wbfmessage.PrepareCode {
			return errExtraSealMessage
		}
		// StateCommit rejects all messages other than msgRoundChange
		return errInvalidMessage
	}
	return nil
}

// It is called on every state change
func (c *Core) processBacklog() {
	c.backlogsMu.Lock()
	defer c.backlogsMu.Unlock()

	for srcAddress, backlog := range c.backlogs {
		if backlog == nil {
			continue
		}
		_, src := c.valSet.GetByAddress(srcAddress)
		if src == nil {
			// validator is not available
			delete(c.backlogs, srcAddress)
			continue
		}
		logger := c.logger.New("from", src, "state", c.state)
		isFuture := false

		logger.Trace("WBFT: process backlog")

		// We stop processing if
		//   1. backlog is empty
		//   2. The first message in queue is a future message
		for !(backlog.Empty() || isFuture) {
			msg, prio := backlog.Pop()

			var code uint64
			var view wbft.View
			var event backlogEvent

			code = msg.Code()
			view = msg.View()
			event.msg = msg

			// Push back if it's a future message
			err := c.checkMessage(code, &view)
			if err != nil && err != errExtraSealMessage {
				if err == errFutureMessage {
					// this is still a future message
					logger.Trace("WBFT: stop processing backlog", "msg", msg)
					backlog.Push(msg, prio)
					isFuture = true
					break
				}
				logger.Trace("WBFT: skip backlog message", "msg", msg, "err", err)
				continue
			}
			logger.Trace("WBFT: post backlog event", "msg", msg)

			event.src = src
			go c.sendEvent(event)
		}
	}
}

// handleRoundChangeMsg is called when receiving a ROUND-CHANGE message from another validator
// - accumulates ROUND-CHANGE messages until reaching quorum for a given round
// - when quorum of ROUND-CHANGE messages is reached then
func (c *Core) handleRoundChangeMsg(roundChange *wbfmessage.RoundChange) error {
	logger := c.currentLogger(true, roundChange)

	view := roundChange.View()
	currentRound := c.currentView().Round

	// number of validators we received ROUND-CHANGE from for a round higher than the current one
	num := c.roundChangeSet.higherRoundMessages(currentRound)

	// number of validators we received ROUND-CHANGE from for the current round
	currentRoundMessages := c.roundChangeSet.getRCMessagesForGivenRound(currentRound)

	logger.Info("WBFT: handle ROUND-CHANGE message", "higherRoundChanges.count", num, "currentRoundChanges.count", currentRoundMessages)

	// Add ROUND-CHANGE message to message set
	if view.Round.Cmp(currentRound) >= 0 {
		var prepareMessages []*wbfmessage.Prepare = nil
		var pr *big.Int = nil
		var pb *types.Block = nil
		if roundChange.PreparedRound != nil && roundChange.PreparedBlock != nil && roundChange.Justification != nil && len(roundChange.Justification) > 0 {
			// We should check the prepared block hash and sequence number
			if roundChange.PreparedBlock.Number().Cmp(c.currentView().Sequence) != 0 {
				err := fmt.Errorf(
					"prepared block number %v does not match current sequence %v",
					roundChange.PreparedBlock.Number().Uint64(),
					c.currentView().Sequence.Uint64(),
				)
				logger.Warn("WBFT: round-change validation failed", "err", err)
				return err
			}
			if roundChange.PreparedBlock.Hash() != roundChange.PreparedDigest {
				err := fmt.Errorf(
					"prepared block hash %s does not match prepared digest %s in ROUND-CHANGE message",
					roundChange.PreparedBlock.Hash().Hex(),
					roundChange.PreparedDigest.Hex(),
				)
				logger.Warn("WBFT: round-change validation failed", "err", err)
				return err
			}
			prepareMessages = roundChange.Justification
			pr = roundChange.PreparedRound
			pb = roundChange.PreparedBlock
		}
		err := c.roundChangeSet.Add(view.Round, roundChange, pr, pb, prepareMessages, c.valSet.QuorumSize())
		if err != nil {
			logger.Warn("WBFT: failed to add ROUND-CHANGE message", "err", err)
			return err
		}
	}

	// number of validators we received ROUND-CHANGE from for a round higher than the current one
	num = c.roundChangeSet.higherRoundMessages(currentRound)

	// number of validators we received ROUND-CHANGE from for the current round
	currentRoundMessages = c.roundChangeSet.getRCMessagesForGivenRound(currentRound)

	logger = logger.New("higherRoundChanges.count", num, "currentRoundChanges.count", currentRoundMessages)

	if float64(num) > c.valSet.F() && float64(num) <= c.valSet.F()+1 {
		// We received F+1 ROUND-CHANGE messages (this may happen before our timeout expired)
		// we start new round and broadcast ROUND-CHANGE message
		newRound := c.roundChangeSet.getMinRoundChange(currentRound)

		logger.Info("WBFT: received F+1 ROUND-CHANGE messages", "F", c.valSet.F())

		c.startNewRound(newRound)
		c.broadcastRoundChange(newRound)
	} else if currentRoundMessages >= c.valSet.QuorumSize() && c.IsProposer() && c.current.preprepareSent.Cmp(currentRound) < 0 {
		logger.Info("WBFT: received quorum of ROUND-CHANGE messages")

		// We received quorum of ROUND-CHANGE for current round and we are proposer

		// If we have received a quorum of PREPARE message
		// then we propose the same block proposal again if not we
		// propose the block proposal that we generated
		_, proposal := c.highestPrepared(currentRound)
		if proposal == nil {
			if c.current != nil && c.current.pendingRequest != nil {
				proposal = c.current.pendingRequest.Proposal
			} else {
				log.Warn("WBFT: round change returns an error: no proposal as pending request is nil")
				return errors.New("no proposal as pending request is nil")
			}
		}

		// Prepare justification for ROUND-CHANGE messages
		roundChangeMessages := c.roundChangeSet.roundChanges[currentRound.Uint64()]
		rcSignedPayloads := make([]*wbfmessage.SignedRoundChangePayload, 0)
		for _, m := range roundChangeMessages.Values() {
			rcMsg := m.(*wbfmessage.RoundChange)
			rcSignedPayloads = append(rcSignedPayloads, &rcMsg.SignedRoundChangePayload)
		}

		prepareMessages := c.roundChangeSet.prepareMessages[currentRound.Uint64()]
		if err := isJustified(proposal, rcSignedPayloads, prepareMessages, c.valSet.QuorumSize()); err != nil {
			logger.Error("WBFT: invalid ROUND-CHANGE message justification", "err", err)
			return nil
		}

		r := &Request{
			Proposal:        proposal,
			RCMessages:      roundChangeMessages,
			PrepareMessages: prepareMessages,
		}
		c.sendPreprepareMsg(r)
	} else {
		logger.Debug("WBFT: accepted ROUND-CHANGE messages")
	}
	return nil
}

// It
// - validates PRE-PREPARE message was created by the right proposer node
// - validates PRE-PREPARE message justification
// - validates PRE-PREPARE message block proposal
func (c *Core) handlePreprepareMsg(preprepare *wbfmessage.Preprepare) error {
	logger := c.currentLogger(true, preprepare)

	logger = logger.New("proposal.number", preprepare.Proposal.Number().Uint64(), "proposal.hash", preprepare.Proposal.Hash().String())

	c.logger.Debug("WBFT: handle PRE-PREPARE message")

	// Validates PRE-PREPARE message comes from current proposer
	if !c.valSet.IsProposer(preprepare.Source()) {
		logger.Warn("WBFT: ignore PRE-PREPARE message from non proposer", "proposer", c.valSet.GetProposer().Address())
		return errNotFromProposer
	}

	// Reject if sequence ≠ proposal number
	if preprepare.Sequence.Uint64() != preprepare.Proposal.Number().Uint64() {
		logger.Warn("WBFT: ignore PRE-PREPARE with mismatched sequence and proposal number")
		return errInvalidPreparedBlock
	}

	// Validates PRE-PREPARE message justification
	if preprepare.Round.Uint64() > 0 {
		if err := isJustified(preprepare.Proposal, preprepare.JustificationRoundChanges, preprepare.JustificationPrepares, c.valSet.QuorumSize()); err != nil {
			logger.Warn("WBFT: invalid PRE-PREPARE message justification", "err", err)
			return errInvalidPreparedBlock
		}
	}

	// Validates PRE-PREPARE block proposal we received
	if duration, err := c.backend.Verify(preprepare.Proposal); err != nil {
		// if it's a future block, we will handle it again after the duration
		if err == consensus.ErrFutureBlock {
			logger.Info("WBFT: PRE-PREPARE block proposal is in the future (will be treated again later)", "duration", duration)

			// start a timer to re-input PRE-PREPARE message as a backlog event
			c.timerMu.Lock()
			c.stopFuturePreprepareTimer()
			c.futurePreprepareTimer = time.AfterFunc(duration, func() {
				_, validator := c.valSet.GetByAddress(preprepare.Source())
				c.sendEvent(backlogEvent{
					src: validator,
					msg: preprepare,
				})
			})
			c.timerMu.Unlock()
		} else {
			logger.Warn("WBFT: invalid PRE-PREPARE block proposal", "err", err)
		}

		return err
	}

	// Here is about to accept the PRE-PREPARE
	if c.state == StateAcceptRequest {
		c.logger.Debug("WBFT: accepted PRE-PREPARE message")

		// Re-initialize ROUND-CHANGE timer
		c.newRoundChangeTimer()
		c.consensusTimestamp = time.Now()

		// Update current state
		c.current.SetPreprepare(preprepare)
		c.setState(StatePreprepared)

		// Broadcast prepare message to other validators
		c.broadcastPrepare()
	}

	return nil
}

// verifyHeader() must catch inconsistent seals before calling this.
func (e *Engine) buildEpochInfo(chain consensus.ChainHeaderReader, header *types.Header, state systemcontracts.StateReader) (*types.EpochInfo, error) {
	var newEpoch types.EpochInfo

	config := chain.Config()
	if isEpoch, _, err := e.IsEpochBlockNumber(config, header.Number); err != nil {
		log.Error("WBFT: failed to determine epoch block", "number", header.Number, "err", err)
		return nil, err
	} else if !isEpoch {
		return nil, nil
	}

	// Generate initial epoch block if a transition occurs.
	if header.Number.Sign() == 0 {
		return wbft.CreateInitialEpochInfo(config.Anzeon)
	}

	proposedSealsInEpoch := make(map[common.Address]int)
	submittedSealsInEpoch := make(map[common.Address]int)
	beingProposerCountInEpoch := make(map[common.Address]int)
	proposers := []common.Address{}
	epochLength := uint64(0)

	var firstProposer, lastProposer common.Address
	latestEpoch, latestEpochInfo, err := e.GetEpochInfo(chain, header, nil)
	if err != nil {
		log.Error("WBFT: failed to get latest epoch info", "number", header.Number, "err", err)
		return nil, err
	}

	validatorsDiff := 0 // latestEpochInfo.Validators - previousEpochInfo.Validators
	// Traverse blocks until reaching the epoch block.
	// Stop counting if the block reaches to the epoch block.
	it := header
	for latestEpoch.Cmp(it.Number) != 0 {
		extra, err := types.ExtractWBFTExtra(it)
		if err != nil {
			log.Error("WBFT: failed to extract wbft extra data", "number", it.Number, "err", err)
			return nil, err
		}

		proposer, err := e.Author(it)
		if err != nil {
			log.Error("WBFT: failed to get proposer", "err", "number", it.Number, err)
			return nil, err
		}
		proposers = append(proposers, proposer)

		parent := chain.GetHeader(it.ParentHash, it.Number.Uint64()-1)
		epochInfo := latestEpochInfo
		if latestEpoch.Cmp(parent.Number) == 0 {
			_, info, err := e.GetEpochInfo(chain, parent, nil)
			if err != nil {
				log.Error("WBFT: failed to get previous epoch info", "number", parent.Number, "err", err)
				return nil, err
			}
			firstProposer, _ = e.Author(it)
			lastProposer, _ = e.Author(parent)
			epochInfo = info

			// Calculate the difference of validator set between two epochs. can be negative.
			validatorsDiff = len(latestEpochInfo.Validators) - len(info.Validators)
		}

		// Accumulate PrevPreparedSeal counts.
		if parent.Number.Sign() == 0 {
			// If the parent block is the genesis block, PrevPreparedSeal is empty.
			// So we don't count proposed seal for the first block.
			beingProposerCountInEpoch[proposer]-- // it will be -1
		} else {
			prepareSigners, err := getSignerAddress(epochInfo, extra.PrevPreparedSeal)
			if err != nil {
				log.Error("WBFT: failed to get previous prepare signers", "number", it.Number, "err", err)
				return nil, err
			}

			proposedSealsInEpoch[proposer] += len(prepareSigners)
			for _, addr := range prepareSigners {
				submittedSealsInEpoch[addr]++
			}

			// Accumulate PrevCommittedSeal counts.
			commitSigners, err := getSignerAddress(epochInfo, extra.PrevCommittedSeal)
			if err != nil {
				log.Error("WBFT: failed to get previous commit signers", "number", it.Number, "err", err)
				return nil, err
			}
			proposedSealsInEpoch[proposer] += len(commitSigners)
			for _, addr := range commitSigners {
				submittedSealsInEpoch[addr]++
			}

			log.Trace("WBFT: Seals count", "current block number", it.Number, "prepareSigners", prepareSigners, "commitSigners", commitSigners)
		}

		// Update current header.
		it = parent
		epochLength++
	}

	candidateMap := make(map[common.Address]*candidateInfo)
	validators := []common.Address{}
	for _, candi := range latestEpochInfo.Candidates {
		candidateMap[candi.Addr] = &candidateInfo{candidate: candi}
	}
	for _, val := range latestEpochInfo.Validators {
		addr := latestEpochInfo.GetCandidate(val)
		candidateMap[addr].isValidator = true
		validators = append(validators, addr)
	}

	// set prior validator
	if it.Number.Cmp(new(big.Int)) > 0 {
		parent := chain.GetHeader(it.ParentHash, it.Number.Uint64()-1)
		_, priorEpochInfo, err2 := e.GetEpochInfo(chain, parent, nil)
		if err2 != nil {
			log.Error("WBFT: failed to get prior epoch info", "number", parent.Number, "err", err2)
			return nil, err2
		}
		for _, val := range priorEpochInfo.Validators {
			addr := priorEpochInfo.GetCandidate(val)
			if candidateMap[addr] != nil { // if candidateMap[addr] == nil -> this is not current candidate
				candidateMap[addr].wasValidator = true
			}
		}
	}

	// Accumulate proposer counts being selected within epoch.
	valSet := validator.NewSet(validators, latestEpochInfo.BLSPublicKeys, e.cfg.GetConfig(header.Number).ProposerPolicy)
	for i := len(proposers) - 1; i >= 0; i-- {
		proposer := proposers[i]
		for round := 0; ; round++ {
			// NOTE: WEMIX uses a round-robin policy to select proposers.
			// If round change occurs for every validators more than once,
			// latest round change cycle window will be used for counting.
			if round >= len(validators) {
				err := errors.New("failed to find valid proposer")
				log.Error("WBFT: Invalid round", "num", header.Number.Uint64(), "err", err)
				return nil, err
			}

			valSet.CalcProposer(lastProposer, uint64(round))
			currP := valSet.GetProposer().Address()
			beingProposerCountInEpoch[currP]++

			if currP == proposer {
				break
			}
		}
		lastProposer = proposer
	}

	log.Trace("WBFT: Seals counts in epoch", "header.number", header.Number,
		"current block number", latestEpoch,
		"proposedSealsInEpoch", proposedSealsInEpoch,
		"submittedSealsInEpoch", submittedSealsInEpoch,
	)

	// Update epoch info.
	newCandidates := e.GetGovCandidates(config, state, header.Number)
	newEpoch.Candidates = make([]*types.Candidate, len(newCandidates))
	for i, candidate := range newCandidates {
		var d uint64

// It
// - validates PREPARE message digest matches the current block proposal
// - accumulates valid PREPARE message until reaching quorum
// - when quorum is reached update states to "Prepared" and broadcast COMMIT
func (c *Core) handlePrepareMsg(prepare *wbfmessage.Prepare) error {
	logger := c.currentLogger(true, prepare).New()

	logger.Debug("WBFT: handle PREPARE message", "prepares.count", c.current.WBFTPrepares.Size(), "quorum", c.valSet.QuorumSize())

	// Check digest
	if prepare.Digest != c.current.Proposal().Hash() {
		logger.Warn("WBFT: invalid PREPARE message digest")
		return errInvalidMessage
	}

	// Check prepareSeal
	block, ok := c.current.Proposal().(*types.Block)
	if !ok {
		logger.Warn("WBFT: failed to cast proposal from PREPARE message to *types.Block")
		return errInvalidMessage
	}

	if verifySeal(c.valSet, block.Header(), uint32(prepare.CommonPayload.Round.Uint64()), SealTypePrepare,
		prepare.PrepareSeal, prepare.Source()) != nil {
		logger.Warn("WBFT: failed to verify seal from PREPARE message", "number", block.Header().Number, "from", prepare.Source())
		return errInvalidMessage
	}

	// Save PREPARE messages
	if err := c.current.WBFTPrepares.Add(prepare); err != nil {
		logger.Error("WBFT: failed to save PREPARE message", "err", err)
		return err
	}

	logger = logger.New("prepares.count", c.current.WBFTPrepares.Size(), "quorum", c.valSet.QuorumSize())

	// Change to "Prepared" state if we've received quorum of PREPARE messages
	// and we are in earlier state than "Prepared"
	if (c.current.WBFTPrepares.Size() >= c.valSet.QuorumSize()) && c.state.Cmp(StatePrepared) < 0 {
		logger.Info("WBFT: received quorum of PREPARE messages")

		// Accumulates PREPARE messages
		c.current.preparedRound = c.currentView().Round
		c.WBFTPreparedPrepares = make([]*wbfmessage.Prepare, 0)
		for _, m := range c.current.WBFTPrepares.Values() {
			c.WBFTPreparedPrepares = append(
				c.WBFTPreparedPrepares,
				wbfmessage.NewPrepareWithSigAndSource(
					m.View().Sequence, m.View().Round, m.(*wbfmessage.Prepare).Digest, m.Signature(), m.Source(), m.(*wbfmessage.Prepare).PrepareSeal))
		}

		if c.current.Proposal() != nil && c.current.Proposal().Hash() == prepare.Digest {
			logger.Trace("WBFT: PREPARE message matches proposal", "proposal", c.current.Proposal().Hash(), "prepare", prepare.Digest)
			c.current.preparedBlock = c.current.Proposal()
		}

		c.setState(StatePrepared)
		c.broadcastCommit()
	} else {
		logger.Trace("WBFT: accepted PREPARE messages")
	}

	return nil
}

// It
// - validates block proposal is not empty and number correspond to the current sequence
// - creates and send PRE-PREPARE message to other validators
func (c *Core) handleRequest(request *Request) error {
	logger := c.currentLogger(true, nil)

	logger.Debug("WBFT: handle block proposal request")

	if err := c.checkRequestMsg(request); err != nil {
		if err == errInvalidMessage {
			logger.Error("WBFT: invalid request")
			return err
		}
		logger.Error("WBFT: unexpected request", "err", err, "number", request.Proposal.Number(), "hash", request.Proposal.Hash())
		return err
	}

	c.current.pendingRequest = request
	if c.state == StateAcceptRequest {
		if c.current.Round().Uint64() == 0 {
			// if round > 0, then we don't send preprepare because it would be failed due to having no justification
			// after that we will send preprepare when 2/3+ round change messages are received
			c.sendPreprepareMsg(request)
		}
	}

	return nil
}

// It
// - creates and sign PRE-PREPARE message with block proposed on `miner.Seal()`
// - extends PRE-PREPARE message with ROUND-CHANGE and PREPARE justification
// - broadcast PRE-PREPARE message to other validators
func (c *Core) sendPreprepareMsg(request *Request) {
	// c.current and c.valSet (checked in IsProposer()) is updated asynchronously in startNewRound(),
	// need to prevent race condition with mutex
	c.currentMutex.Lock()
	defer c.currentMutex.Unlock()

	logger := c.currentLogger(true, nil)

	// If I'm the proposer and I have the same sequence with the proposal
	if c.current.Sequence().Cmp(request.Proposal.Number()) == 0 && c.IsProposer() {
		// Creates PRE-PREPARE message
		curView := c.currentView()
		preprepare := wbfmessage.NewPreprepare(curView.Sequence, curView.Round, request.Proposal)
		preprepare.SetSource(c.Address())

		// Sign payload
		encodedPayload, err := preprepare.EncodePayloadForSigning()
		if err != nil {
			withMsg(logger, preprepare).Error("WBFT: failed to encode payload of PRE-PREPARE message", "err", err)
			return
		}
		signature, err := c.backend.Sign(encodedPayload)
		if err != nil {
			withMsg(logger, preprepare).Error("WBFT: failed to sign PRE-PREPARE message", "err", err)
			return
		}
		preprepare.SetSignature(signature)

		// Extend PRE-PREPARE message with ROUND-CHANGE justification
		if request.RCMessages != nil {
			preprepare.JustificationRoundChanges = make([]*wbfmessage.SignedRoundChangePayload, 0)
			for _, m := range request.RCMessages.Values() {
				preprepare.JustificationRoundChanges = append(preprepare.JustificationRoundChanges, &m.(*wbfmessage.RoundChange).SignedRoundChangePayload)
				withMsg(logger, preprepare).Trace("WBFT: add ROUND-CHANGE justification", "rc", m.(*wbfmessage.RoundChange).SignedRoundChangePayload)
			}
			withMsg(logger, preprepare).Trace("WBFT: extended PRE-PREPARE message with ROUND-CHANGE justifications", "justifications", preprepare.JustificationRoundChanges)
		}

		// Extend PRE-PREPARE message with PREPARE justification
		if request.PrepareMessages != nil {
			preprepare.JustificationPrepares = request.PrepareMessages
			withMsg(logger, preprepare).Trace("WBFT: extended PRE-PREPARE message with PREPARE justification", "justification", preprepare.JustificationPrepares)
		}

		// RLP-encode message
		payload, err := rlp.EncodeToBytes(&preprepare)
		if err != nil {
			withMsg(logger, preprepare).Error("WBFT: failed to encode PRE-PREPARE message", "err", err)
			return
		}

		logger = withMsg(logger, preprepare).New("block.number", preprepare.Proposal.Number().Uint64(), "block.hash", preprepare.Proposal.Hash().String())

		logger.Info("WBFT: broadcast PRE-PREPARE message")
		logger.Trace("WBFT: PRE-PREPARE payload", "payload", hexutil.Encode(payload))

		// Broadcast RLP-encoded message
		if err = c.backend.Broadcast(c.valSet, preprepare.Code(), payload); err != nil {
			logger.Error("WBFT: failed to broadcast PRE-PREPARE message", "err", err)
			return
		}

		// Set the preprepareSent to the current round
		c.current.preprepareSent = curView.Round
	}
}

type Lifecycle interface {
	// Start is called after all services have been constructed and the networking
	// layer was also initialized to spawn any goroutines required by the service.
	Start() error

	// Stop terminates all goroutines belonging to the service, blocking until they
	// are all terminated.
	Stop() error
}

func (h Hash) String() string {
	return h.Hex()
}

func (c *Core) setState(state State) {
	if c.state != state {
		oldState := c.state
		c.state = state
		c.currentLogger(false, nil).Debug("WBFT: changed state", "old.state", oldState.String(), "new.state", state.String())
	}
	if state == StateAcceptRequest {
		c.processPendingRequests()
	}

	// each time we change state, we process backlog for possible message that are
	// now ready
	c.processBacklog()
}

// GetSystemContractsTransition builds a StateTransition for the given SystemContracts.
//
// Upgrade principle — Code only:
// Hardfork upgrades ONLY deploy new contract code. On-chain state (storage slots)
// is NEVER modified during an upgrade. State values set at genesis (v1) or changed
// through governance proposals are always preserved as-is.
//
// Version-based behavior:
//   - "v1": Code deployment + State initialization (genesis only)
//   - other: Code deployment only, no state changes
//
// IMPORTANT: Each contract's initial version MUST be "v1". The initialize*() functions
// (e.g., initializeValidator, initializeCoinAdapter) are only invoked when Version == "v1",
// and they set up the required storage layout (owner, quorum, members, etc.).
// Starting with any other version will skip initialization, leaving the contract in an
// uninitialized state with empty storage — which will cause runtime failures.
func GetSystemContractsTransition(systemContracts *params.SystemContracts, alloc *types.GenesisAlloc) (*params.StateTransition, error) {
	st := &params.StateTransition{}

	if systemContracts.GovValidator != nil {
		code, err := getContractCode(CONTRACT_GOV_VALIDATOR, systemContracts.GovValidator.Version)
		if err != nil {
			return nil, err
		}
		st.Codes = append(st.Codes, params.CodeParam{Address: systemContracts.GovValidator.Address, Code: code})
		if systemContracts.GovValidator.Params != nil && systemContracts.GovValidator.Version == SYSTEM_CONTRACT_VERSION_1 {
			sp, err := initializeValidator(systemContracts.GovValidator.Address, systemContracts.GovValidator.Params)
			if err != nil {
				return nil, err
			}
			st.States = append(st.States, sp...)
		}
	}

	if systemContracts.NativeCoinAdapter != nil {
		code, err := getContractCode(CONTRACT_COIN_ADAPTER, systemContracts.NativeCoinAdapter.Version)
		if err != nil {
			return nil, err
		}
		st.Codes = append(st.Codes, params.CodeParam{Address: systemContracts.NativeCoinAdapter.Address, Code: code})
		if systemContracts.NativeCoinAdapter.Params != nil && systemContracts.NativeCoinAdapter.Version == SYSTEM_CONTRACT_VERSION_1 {
			sp, err := initializeCoinAdapter(systemContracts.NativeCoinAdapter.Address, systemContracts.NativeCoinAdapter.Params, alloc)
			if err != nil {
				return nil, err
			}
			st.States = append(st.States, sp...)
		}
	}

	if systemContracts.GovMinter != nil {
		code, err := getContractCode(CONTRACT_GOV_MINTER, systemContracts.GovMinter.Version)
		if err != nil {
			return nil, err
		}
		st.Codes = append(st.Codes, params.CodeParam{Address: systemContracts.GovMinter.Address, Code: code})
		if systemContracts.GovMinter.Params != nil && systemContracts.GovMinter.Version == SYSTEM_CONTRACT_VERSION_1 {
			sp, err := initializeMinter(systemContracts.GovMinter.Address, systemContracts.GovMinter.Params)
			if err != nil {
				return nil, err
			}
			st.States = append(st.States, sp...)
		}
	}

	if systemContracts.GovMasterMinter != nil {
		code, err := getContractCode(CONTRACT_GOV_MASTER_MINTER, systemContracts.GovMasterMinter.Version)
		if err != nil {
			return nil, err
		}
		st.Codes = append(st.Codes, params.CodeParam{Address: systemContracts.GovMasterMinter.Address, Code: code})
		if systemContracts.GovMasterMinter.Params != nil && systemContracts.GovMasterMinter.Version == SYSTEM_CONTRACT_VERSION_1 {
			sp, err := initializeMasterMinter(systemContracts.GovMasterMinter.Address, systemContracts.GovMasterMinter.Params)
			if err != nil {
				return nil, err
			}
			st.States = append(st.States, sp...)
		}
	}

	if systemContracts.GovCouncil != nil {
		code, err := getContractCode(CONTRACT_GOV_COUNCIL, systemContracts.GovCouncil.Version)
		if err != nil {
			return nil, err
		}
		st.Codes = append(st.Codes, params.CodeParam{Address: systemContracts.GovCouncil.Address, Code: code})
		if systemContracts.GovCouncil.Params != nil && systemContracts.GovCouncil.Version == SYSTEM_CONTRACT_VERSION_1 {
			sp, err := initializeGovCouncil(systemContracts.GovCouncil.Address, systemContracts.GovCouncil.Params, alloc)
			if err != nil {
				return nil, err
			}
			st.States = append(st.States, sp...)
		}
	}

	return st, nil
}

// Process processes the state changes according to the Ethereum rules by running
// the transaction messages using the statedb and applying any rewards to both
// the processor (coinbase) and any included uncles.
//
// Process returns the receipts and logs accumulated during the process and
// returns the amount of gas that was used in the process. If any of the
// transactions failed to execute due to insufficient gas it will return an error.
func (p *StateProcessor) Process(block *types.Block, statedb *state.StateDB, cfg vm.Config) (types.Receipts, []*types.Log, uint64, error) {
	var (
		receipts    types.Receipts
		usedGas     = new(uint64)
		header      = block.Header()
		blockHash   = block.Hash()
		blockNumber = block.Number()
		allLogs     []*types.Log
		gp          = new(GasPool).AddGas(block.GasLimit())
	)
	// Mutate the block and state according to any hard-fork specs
	if p.config.DAOForkSupport && p.config.DAOForkBlock != nil && p.config.DAOForkBlock.Cmp(block.Number()) == 0 {
		misc.ApplyDAOHardFork(statedb)
	}
	var (
		context = NewEVMBlockContext(header, p.bc, nil)
		vmenv   = vm.NewEVM(context, vm.TxContext{}, statedb, p.config, cfg)
		signer  = types.MakeSigner(p.config, header.Number, header.Time)
	)
	if beaconRoot := block.BeaconRoot(); beaconRoot != nil {
		ProcessBeaconBlockRoot(*beaconRoot, vmenv, statedb)
	}
	// Iterate over and process the individual transactions
	for i, tx := range block.Transactions() {
		msg, err := TransactionToMessage(tx, signer, header.BaseFee, header.GasTip(), statedb)
		if err != nil {
			return nil, nil, 0, fmt.Errorf("could not apply tx %d [%v]: %w", i, tx.Hash().Hex(), err)
		}
		statedb.SetTxContext(tx.Hash(), i)
		receipt, err := applyTransaction(msg, p.config, gp, statedb, blockNumber, blockHash, tx, usedGas, vmenv)
		if err != nil {
			return nil, nil, 0, fmt.Errorf("could not apply tx %d [%v]: %w", i, tx.Hash().Hex(), err)
		}
		receipts = append(receipts, receipt)
		allLogs = append(allLogs, receipt.Logs...)
	}
	// Fail if Shanghai not enabled and len(withdrawals) is non-zero.
	withdrawals := block.Withdrawals()
	if len(withdrawals) > 0 && !p.config.IsShanghai(block.Number(), block.Time()) {
		return nil, nil, 0, errors.New("withdrawals before shanghai")
	}
	// Finalize the block, applying any consensus engine specific extras (e.g. block rewards)
	if err := p.engine.Finalize(p.bc, header, statedb, block.Transactions(), block.Uncles(), withdrawals); err != nil {
		return nil, nil, 0, err
	}

	return receipts, allLogs, *usedGas, nil
}

// TransitionDb will transition the state by applying the current message and
// returning the evm execution result with following fields.
//
//   - used gas: total gas used (including gas being refunded)
//   - returndata: the returned data from evm
//   - concrete execution error: various EVM errors which abort the execution, e.g.
//     ErrOutOfGas, ErrExecutionReverted
//
// However if any consensus issue encountered, return the error directly with
// nil evm execution result.
func (st *StateTransition) TransitionDb() (*ExecutionResult, error) {
	// First check this message satisfies all consensus rules before
	// applying the message. The rules include these clauses
	//
	// 1. the nonce of the message caller is correct
	// 2. caller has enough balance to cover transaction fee(gaslimit * gasprice)
	// 3. the amount of gas required is available in the block
	// 4. the purchased gas is enough to cover intrinsic usage
	// 5. there is no overflow when calculating intrinsic gas
	// 6. caller has enough balance to cover asset transfer for **topmost** call

	// Check clauses 1-3, buy gas if everything is correct
	if err := st.preCheck(); err != nil {
		return nil, err
	}

	if tracer := st.evm.Config.Tracer; tracer != nil {
		tracer.CaptureTxStart(st.evm, st.initialGas, st.msg.SetCodeAuthorizations)
		defer func() {
			tracer.CaptureTxEnd(st.gasRemaining)
		}()
	}

	var (
		msg              = st.msg
		sender           = vm.AccountRef(msg.From)
		rules            = st.evm.ChainConfig().Rules(st.evm.Context.BlockNumber, (st.evm.Context.Difficulty == nil || st.evm.Context.Difficulty.Cmp(common.Big0) == 0) && st.evm.Context.Random != nil, st.evm.Context.Time)
		contractCreation = msg.To == nil
	)

	// Check clauses 4-5, subtract intrinsic gas if everything is correct
	gas, err := IntrinsicGas(msg.Data, msg.AccessList, msg.SetCodeAuthorizations, contractCreation, rules.IsHomestead, rules.IsIstanbul, rules.IsShanghai)
	if err != nil {
		return nil, err
	}
	if st.gasRemaining < gas {
		return nil, fmt.Errorf("%w: have %d, want %d", ErrIntrinsicGas, st.gasRemaining, gas)
	}
	st.gasRemaining -= gas

	// Check clause 6
	value, overflow := uint256.FromBig(msg.Value)
	if overflow {
		return nil, fmt.Errorf("%w: address %v", ErrInsufficientFundsForTransfer, msg.From.Hex())
	}
	if !value.IsZero() && !st.evm.Context.CanTransfer(st.state, msg.From, value) {
		return nil, fmt.Errorf("%w: address %v", ErrInsufficientFundsForTransfer, msg.From.Hex())
	}

	// Check whether the init code size has been exceeded.
	if rules.IsShanghai && contractCreation && len(msg.Data) > params.MaxInitCodeSize {
		return nil, fmt.Errorf("%w: code size %v limit %v", ErrMaxInitCodeSizeExceeded, len(msg.Data), params.MaxInitCodeSize)
	}

	// Transfer Validation Hook - Check blacklist for Anzeon network
	if rules.IsAnzeon {
		// Check sender blacklist
		if st.state.IsBlacklisted(msg.From) {
			return nil, &ErrBlacklistedAccount{Address: msg.From}
		}

		// Check recipient blacklist (only for transfers, not for contract creation)
		if msg.To != nil && st.state.IsBlacklisted(*msg.To) {
			return nil, &ErrBlacklistedAccount{Address: *msg.To}
		}
	}

	// Execute the preparatory steps for state transition which includes:
	// - prepare accessList(post-berlin)
	// - reset transient storage(eip 1153)
	st.state.Prepare(rules, msg.From, st.evm.Context.Coinbase, msg.To, vm.ActivePrecompiles(rules), vm.ActiveNativeManagers(rules), msg.AccessList)

	var (
		ret   []byte
		vmerr error // vm errors do not effect consensus and are therefore not assigned to err
	)
	if contractCreation {
		ret, _, st.gasRemaining, vmerr = st.evm.Create(sender, msg.Data, st.gasRemaining, value)
	} else {
		// Increment the nonce for the next transaction.
		st.state.SetNonce(msg.From, st.state.GetNonce(msg.From)+1)

		// Apply EIP-7702 authorizations.
		if msg.SetCodeAuthorizations != nil {
			for _, auth := range msg.SetCodeAuthorizations {
				// Note errors are ignored, we simply skip invalid authorizations here.
				st.applyAuthorization(msg, &auth)
			}
		}

		// Perform convenience warming of sender's delegation target. Although the
		// sender is already warmed in Prepare(..), it's possible a delegation to
		// the account was deployed during this transaction. To handle correctly,
		// simply wait until the final state of delegations is determined before
		// performing the resolution and warming.
		if addr, ok := types.ParseDelegation(st.state.GetCode(*msg.To)); ok {
			st.state.AddAddressToAccessList(addr)
		}

		// Execute the transaction's call.
		ret, st.gasRemaining, vmerr = st.evm.Call(sender, st.to(), msg.Data, st.gasRemaining, value)
	}

	var gasRefund uint64
	if !rules.IsLondon {
		// Before EIP-3529: refunds were capped to gasUsed / 2
		gasRefund = st.refundGas(params.RefundQuotient)
	} else {
		// After EIP-3529: refunds are capped to gasUsed / 5
		gasRefund = st.refundGas(params.RefundQuotientEIP3529)
	}

	effectiveTip := msg.GasPrice
	if rules.IsLondon {
		effectiveTip = cmath.BigMin(msg.GasTipCap, new(big.Int).Sub(msg.GasFeeCap, st.evm.Context.BaseFee))
	}
	effectiveTipU256, _ := uint256.FromBig(effectiveTip)

	if st.evm.Config.NoBaseFee && msg.GasFeeCap.Sign() == 0 && msg.GasTipCap.Sign() == 0 {
		// Skip fee payment when NoBaseFee is set and the fee fields
		// are 0. This avoids a negative effectiveTip being applied to
		// the coinbase when simulating calls.
	} else {
		fee := new(uint256.Int).SetUint64(st.gasUsed())
		fee.Mul(fee, effectiveTipU256)
		st.state.AddBalance(st.evm.Context.Coinbase, fee)

		// fee delegation
		if st.msg.FeePayer != nil {
			payer := *st.msg.FeePayer
			if rules.IsAnzeon && st.state.IsBlacklisted(payer) {
				return nil, &ErrBlacklistedAccount{Address: payer}
			}
		}
	}

contract GovValidator is GovBase {
    using EnumerableSet for EnumerableSet.AddressSet;

    uint256 public constant BLS_PUBLIC_KEY_LENGTH = 48;
    uint256 public constant BLS_SIGNATURE_LENGTH = 96;

    error InvalidValidator();
    error AlreadyValidatorExists();
    error NoConfigurationChanging();
    error InvalidBlsKeyLength();
    error InvalidSignatureLength();
    error AlreadyRegisteredBlsKey();
    error FailedToVerifyBlsKey();
    error InvalidBlsKey();
    error InvalidGasTip();
    error SameGasTip();

    // 0x0 ~ 0x31: reserved for GovBase
    address public blsPoP; // 0x32; Precompiled contract address for BLS PoP verification
    EnumerableSet.AddressSet private __validators; // 0x33, 0x34; validator addresses
    mapping(address => address) public validatorToOperator; // 0x35
    mapping(address => address) public operatorToValidator; // 0x36
    mapping(address => bytes) public validatorToBlsKey; // 0x37
    mapping(bytes => address) public blsKeyToValidator; // 0x38
    uint256 public gasTip; // 0x39

    // ========== Action Types ==========
    bytes32 public constant ACTION_SET_GAS_TIP = keccak256("SET_GAS_TIP");

    function isValidator(address _validator) external view returns (bool) {
        return __validators.contains(_validator);
    }

    function validatorList() external view returns (address[] memory) {
        return __validators.values();
    }

    function validatorCount() external view returns (uint256) {
        return __validators.length();
    }

    function configureValidator(address _newValidator, bytes calldata _blsKey, bytes calldata _blsSig) external onlyActiveMember {
        if (_newValidator == address(0)) {
            revert InvalidValidator();
        }
        if (validatorToOperator[_newValidator] != address(0) && validatorToOperator[_newValidator] != msg.sender) {
            // _newValidator is already registered by other operator
            revert AlreadyValidatorExists();
        }
        _checkBlsKey(_blsKey, _blsSig);

        address _oldValidator = operatorToValidator[msg.sender];
        if (blsKeyToValidator[_blsKey] != address(0) && blsKeyToValidator[_blsKey] != _oldValidator) {
            revert AlreadyRegisteredBlsKey();
        }

        // case 1: register new validator
        // case 2: change BLS key only
        // case 3: change validator address with changing BLS key (bls key can be same as old one)
        if (_oldValidator == address(0)) {
            // case 1
            _setValidatorAndBlsKey(_newValidator, _blsKey);
        } else if (_oldValidator == _newValidator) {
            // case 2
            if (blsKeyToValidator[_blsKey] == _oldValidator) {
                revert NoConfigurationChanging();
            }
            _changeBlsKey(_oldValidator, _blsKey);
        } else {
            // case 3
            _changeValidator(_oldValidator, _newValidator, _blsKey);
        }
    }

    function _setValidatorAndBlsKey(address _newValidator, bytes calldata _blsKey) internal {
        __validators.add(_newValidator);
        operatorToValidator[msg.sender] = _newValidator;
        validatorToOperator[_newValidator] = msg.sender;
        _setBlsKey(_newValidator, _blsKey);
    }

    function _setBlsKey(address _validator, bytes calldata _blsKey) internal {
        validatorToBlsKey[_validator] = _blsKey;
        blsKeyToValidator[_blsKey] = _validator;
    }

    function _changeBlsKey(address _validator, bytes calldata _blsKey) internal {
        delete blsKeyToValidator[validatorToBlsKey[_validator]];
        _setBlsKey(_validator, _blsKey);
    }

    function _changeValidator(address _oldValidator, address _newValidator, bytes calldata _blsKey) internal {
        _removeValidator(_oldValidator, msg.sender);

        _setValidatorAndBlsKey(_newValidator, _blsKey);
    }

    function _removeValidator(address _validator, address _member) internal {
        __validators.remove(_validator);
        delete validatorToOperator[_validator];
        delete operatorToValidator[_member];
        delete blsKeyToValidator[validatorToBlsKey[_validator]];
        delete validatorToBlsKey[_validator];
    }

    function _onMemberRemoved(address _member) internal override {
        address _validator = operatorToValidator[_member];
        if (_validator != address(0)) {
            _removeValidator(_validator, _member);
        }
    }

    function _onMemberAdded(address _member) internal override {
        // do nothing
    }

    function _onMemberChanged(address _oldMember, address _newMember) internal override {
        address _validator = operatorToValidator[_oldMember];
        if (_validator != address(0)) {
            operatorToValidator[_newMember] = _validator;
            validatorToOperator[_validator] = _newMember;
            delete operatorToValidator[_oldMember];
        }
    }

    function _executeCustomAction(bytes32 actionType, bytes memory callData) internal override returns (bool) {
        if (actionType == ACTION_SET_GAS_TIP) {
            uint256 _newTip = abi.decode(callData, (uint256));
            _setGasTip(_newTip);
            return true;
        }
        return false;
    }

    function _checkBlsKey(bytes calldata _blsKey, bytes calldata _blsSig) internal view {
        if (_blsKey.length != BLS_PUBLIC_KEY_LENGTH) {
            revert InvalidBlsKeyLength();
        }
        if (_blsSig.length != BLS_SIGNATURE_LENGTH) {
            revert InvalidSignatureLength();
        }

        (bool _success, bytes memory _result) = blsPoP.staticcall(abi.encodePacked(_blsKey, _blsSig));
        if (!_success) {
            revert FailedToVerifyBlsKey();
        }
        if (!abi.decode(_result, (bool))) {
            revert InvalidBlsKey();
        }
    }

    // ========== Events ==========
    event GasTipUpdated(uint256 oldTip, uint256 newTip, address indexed updater);

func initializeCoinAdapter(coinAdapterAddress common.Address, param map[string]string, alloc *types.GenesisAlloc) ([]params.StateParam, error) {
	sp := make([]params.StateParam, 0)

	// SLOT_COIN_ADAPTER_MASTER_MINTER
	masterMinter, ok := param[COIN_ADAPTER_PARAM_MASTER_MINTER]
	if !ok || len(masterMinter) == 0 {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: missing parameter: %s", COIN_ADAPTER_PARAM_MASTER_MINTER)
	}
	sp = append(sp, params.StateParam{
		Address: coinAdapterAddress,
		Key:     common.HexToHash(SLOT_COIN_ADAPTER_MASTER_MINTER),
		Value:   common.BytesToHash(common.HexToAddress(masterMinter).Bytes()),
	})

	// SLOT_COIN_ADAPTER_MINTERS, SLOT_COIN_ADAPTER_MINTER_ALLOWED
	if mintersStr, ok := param[COIN_ADAPTER_PARAM_MINTERS]; ok && len(mintersStr) > 0 {
		minters := splitAndTrim(mintersStr, ",")
		minterAllowedAmounts := make([]*big.Int, len(minters))
		if minterAllowedStr, ok := param[COIN_ADAPTER_PARAM_MINTER_ALLOWED]; ok && len(minterAllowedStr) > 0 {
			minterAllowed := splitAndTrim(minterAllowedStr, ",")
			if len(minters) != len(minterAllowed) {
				return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: the number of minters and minterAllowedAmounts must be the same")
			}
			for i, allowed := range minterAllowed {
				allowedAmount, ok := new(big.Int).SetString(allowed, 10)
				if !ok {
					return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: invalid minterAllowed, must be decimal")
				}
				minterAllowedAmounts[i] = allowedAmount
			}
		}
		mintersSlot := common.HexToHash(SLOT_COIN_ADAPTER_MINTERS)
		minterAllowedSlot := common.HexToHash(SLOT_COIN_ADAPTER_MINTER_ALLOWED)
		for i, minter := range minters {
			minterAddress := common.HexToAddress(minter)
			sp = append(sp, params.StateParam{
				Address: coinAdapterAddress,
				Key:     CalculateMappingSlot(mintersSlot, minterAddress),
				Value:   common.BytesToHash([]byte{1}), // == true
			})

			if minterAllowedAmounts[i] != nil {
				sp = append(sp, params.StateParam{
					Address: coinAdapterAddress,
					Key:     CalculateMappingSlot(minterAllowedSlot, minterAddress),
					Value:   common.BigToHash(minterAllowedAmounts[i]),
				})
			}
		}
	}

	// SLOT_COIN_ADAPTER_COIN_MANAGER
	sp = append(sp, params.StateParam{
		Address: coinAdapterAddress,
		Key:     common.HexToHash(SLOT_COIN_ADAPTER_COIN_MANAGER),
		Value:   common.BytesToHash(params.NativeCoinManagerAddress.Bytes()),
	})

	// SLOT_COIN_ADAPTER_ACCOUNT_MANAGER
	sp = append(sp, params.StateParam{
		Address: coinAdapterAddress,
		Key:     common.HexToHash(SLOT_COIN_ADAPTER_ACCOUNT_MANAGER),
		Value:   common.BytesToHash(params.AccountManagerAddress.Bytes()),
	})

	// SLOT_COIN_ADAPTER_NAME
	coinName, ok := param[COIN_ADAPTER_PARAM_NAME]
	if !ok || len(coinName) == 0 {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: missing parameter: %s", COIN_ADAPTER_PARAM_NAME)
	}
	for slot, value := range EncodeBytesToSlots(common.HexToHash(SLOT_COIN_ADAPTER_NAME), []byte(coinName)) {
		sp = append(sp, params.StateParam{
			Address: coinAdapterAddress,
			Key:     slot,
			Value:   value,
		})
	}

	// SLOT_COIN_ADAPTER_SYMBOL
	symbol, ok := param[COIN_ADAPTER_PARAM_SYMBOL]
	if !ok || len(symbol) == 0 {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: missing parameter: %s", COIN_ADAPTER_PARAM_SYMBOL)
	}
	for slot, value := range EncodeBytesToSlots(common.HexToHash(SLOT_COIN_ADAPTER_SYMBOL), []byte(symbol)) {
		sp = append(sp, params.StateParam{
			Address: coinAdapterAddress,
			Key:     slot,
			Value:   value,
		})
	}

	// SLOT_COIN_ADAPTER_DECIMALS
	decimalsStr, ok := param[COIN_ADAPTER_PARAM_DECIMALS]
	if !ok || len(decimalsStr) == 0 {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: missing parameter: %s", COIN_ADAPTER_PARAM_DECIMALS)
	}
	decimals, err := strconv.ParseUint(decimalsStr, 10, 8)
	if err != nil {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params.decimals`: %w", err)
	}
	sp = append(sp, params.StateParam{
		Address: coinAdapterAddress,
		Key:     common.HexToHash(SLOT_COIN_ADAPTER_DECIMALS),
		Value:   common.BytesToHash([]byte{uint8(decimals)}),
	})

	// SLOT_COIN_ADAPTER_CURRENCY
	currency, ok := param[COIN_ADAPTER_PARAM_CURRENCY]
	if !ok || len(currency) == 0 {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: missing parameter: %s", COIN_ADAPTER_PARAM_CURRENCY)
	}
	for slot, value := range EncodeBytesToSlots(common.HexToHash(SLOT_COIN_ADAPTER_CURRENCY), []byte(currency)) {
		sp = append(sp, params.StateParam{
			Address: coinAdapterAddress,
			Key:     slot,
			Value:   value,
		})
	}

	// SLOT_COIN_ADAPTER_TOTAL_SUPPLY
	if alloc != nil {
		totalSupply := new(big.Int)
		for _, account := range *alloc {
			if account.Balance != nil {
				totalSupply.Add(totalSupply, account.Balance)
			}
		}
		sp = append(sp, params.StateParam{
			Address: coinAdapterAddress,
			Key:     common.HexToHash(SLOT_COIN_ADAPTER_TOTAL_SUPPLY),
			Value:   common.BigToHash(totalSupply),
		})
	}

	return sp, nil
}

func getContractCode(contractType, version string) (string, error) {
	versions, ok := SystemContractCodes[contractType]
	if !ok {
		return "", fmt.Errorf("unknown contract type: %s", contractType)
	}
	code, ok := versions[version]
	if !ok || code == "" {
		return "", fmt.Errorf("unsupported version %s for contract %s", version, contractType)
	}
	return code, nil
}

type SystemContract struct {
	Address common.Address    `json:"address"`
	Version string            `json:"version"`
	Params  map[string]string `json:"params"`
}

func (m *CommonPayload) Code() uint64 {
	return m.code
}

// CollectUpgrades returns all system contract hardfork upgrades defined in the chain config.
// This is the single source of truth for hardfork registration — all consumers
// (genesis initialization, WBFT engine config, runtime block finalization) rely
// on this function to discover which upgrades exist.
//
// IMPORTANT — ordering contract:
//   - Entries MUST be appended in strictly ascending block number order.
//   - checkConfigForkOrder() enforces this at node startup; violation panics.
//   - Block 0 hardforks are applied during genesis (via InjectContracts).
//   - Block > 0 hardforks are applied at runtime during block finalization.
//   - System contract versions MUST increase monotonically with block height.
//     e.g., GovMinter v2 at block 100, v3 at block 200 is valid.
//     GovMinter v3 at block 100, v2 at block 200 is INVALID — a higher
//     version at a lower block implies a downgrade, which is not supported.
//
// To add a new hardfork (e.g., "CFork"):
//  1. Add CForkBlock + CFork fields to ChainConfig.
//  2. Append one entry below, AFTER the last existing hardfork (Boho).
//     The append order here must match checkConfigForkOrder().
func (c *ChainConfig) CollectUpgrades() []Upgrade {
	var upgrades []Upgrade

	// ── Hardfork Registry (ascending block order) ─────────

	// Boho hardfork — GovMinter v2 (burn/refund mechanism)
	if c.BohoBlock != nil && c.Boho != nil && c.Boho.SystemContracts != nil {
		upgrades = append(upgrades, Upgrade{
			Block:           c.BohoBlock,
			SystemContracts: c.Boho.SystemContracts,
		})
	}

	// NEW HARDFORKS GO HERE — always append after the last entry above.

	// ──────────────────────────────────────────────────────

	return upgrades
}

