func (rcs *roundChangeSet) NewRound(r *big.Int) {
	rcs.mu.Lock()
	defer rcs.mu.Unlock()
	round := r.Uint64()
	if rcs.roundChanges[round] == nil {
		rcs.roundChanges[round] = newWBFTMsgSet(rcs.validatorSet)
	}
	if rcs.prepareMessages[round] == nil {
		rcs.prepareMessages[round] = make([]*wbfmessage.Prepare, 0)
	}
}

// newRoundState creates a new roundState instance with the given view and validatorSet
func newRoundState(view *wbft.View, validatorSet wbft.ValidatorSet, preprepare *wbfmessage.Preprepare, preparedRound *big.Int, preparedBlock wbft.Proposal, pendingRequest *Request, hasBadProposal func(hash common.Hash) bool) *roundState {
	return &roundState{
		round:      view.Round,
		sequence:   view.Sequence,
		Preprepare: preprepare,
		//Prepares:       newMessageSet(validatorSet),
		//Commits:        newMessageSet(validatorSet),
		WBFTPrepares:   newWBFTMsgSet(validatorSet),
		WBFTCommits:    newWBFTMsgSet(validatorSet),
		preparedRound:  preparedRound,
		preparedBlock:  preparedBlock,
		mu:             new(sync.RWMutex),
		pendingRequest: pendingRequest,
		hasBadProposal: hasBadProposal,
		preprepareSent: big.NewInt(0),
	}
}

// startNewRound starts a new round. if round equals to 0, it means to starts a new sequence
func (c *Core) startNewRound(round *big.Int) {
	c.currentMutex.Lock()
	defer c.currentMutex.Unlock()

	var logger log.Logger
	if c.current == nil {
		logger = c.logger.New("old.round", -1, "old.seq", 0)
	} else {
		logger = c.currentLogger(false, nil)
	}
	logger = logger.New("target.round", round)

	roundChange := false

	// Try to get last proposal
	lastProposal, lastProposer := c.backend.LastProposal()
	if lastProposal != nil {
		logger = logger.New("lastProposal.number", lastProposal.Number().Uint64(), "lastProposal.hash", lastProposal.Hash())
	}

	logger.Debug("WBFT: initialize new round")

	if c.current == nil {
		logger.Debug("WBFT: start at the initial round")
	} else if lastProposal.Number().Cmp(c.current.Sequence()) >= 0 {
		diff := new(big.Int).Sub(lastProposal.Number(), c.current.Sequence())
		sequenceMeter.Mark(new(big.Int).Add(diff, common.Big1).Int64())

		if !c.consensusTimestamp.IsZero() {
			consensusTimer.UpdateSince(c.consensusTimestamp)
			c.consensusTimestamp = time.Time{}
		}
		logger.Debug("WBFT: catch up last block proposal")
	} else if lastProposal.Number().Cmp(big.NewInt(c.current.Sequence().Int64()-1)) == 0 {
		if round.Cmp(common.Big0) == 0 {
			// same seq and round, don't need to start new round
			logger.Debug("WBFT: same round, no need to start new round")
			return
		} else if round.Cmp(c.current.Round()) < 0 {
			logger.Warn("WBFT: next round is inferior to current round")
			return
		}
		roundChange = true
	} else {
		logger.Warn("WBFT: next sequence is before last block proposal")
		return
	}

	var oldLogger log.Logger
	if c.current == nil {
		oldLogger = c.logger.New("old.round", -1, "old.seq", 0)
	} else {
		oldLogger = c.logger.New("old.round", c.current.Round().Uint64(), "old.sequence", c.current.Sequence().Uint64(), "old.state", c.state.String(), "old.proposer", c.valSet.GetProposer())
	}

	if c.current != nil && round.Cmp(c.current.Round()) > 0 {
		roundMeter.Mark(new(big.Int).Sub(round, c.current.Round()).Int64())
	}

	// Create next view
	var newView *wbft.View
	var nextValSet wbft.ValidatorSet
	if roundChange {
		newView = &wbft.View{
			Sequence: new(big.Int).Set(c.current.Sequence()),
			Round:    new(big.Int).Set(round),
		}
		nextValSet = c.valSet
	} else {
		newView = &wbft.View{
			Sequence: new(big.Int).Add(lastProposal.Number(), common.Big1),
			Round:    new(big.Int),
		}
		nextValSet = c.backend.Validators(lastProposal)

		// Add extra seal that contributed to consensus
		c.addEffectiveSealToExtraSeal()
	}

	// New snapshot for new round
	c.updateRoundState(nextValSet, newView, roundChange)

	// Calculate new proposer
	c.valSet.CalcProposer(lastProposer, newView.Round.Uint64())
	c.setState(StateAcceptRequest)

	// Update RoundChangeSet by deleting older round messages
	if round.Uint64() == 0 {
		c.WBFTPreparedPrepares = nil
		c.roundChangeSet = newRoundChangeSet(c.valSet)
		c.ClearExtraSeals(lastProposal.Number())
	} else {
		// Clear earlier round messages
		c.roundChangeSet.ClearLowerThan(round)
	}
	c.roundChangeSet.NewRound(round)

	c.backend.NotifyNewRound(round)

	// the order of NotifyNewRound() and newRoundChangeTimer() does not matter on actual consensus, but
	// it matters on multi-engine test, so we keep the order as it is
	c.newRoundChangeTimer()

	oldLogger.Info("WBFT: start new round", "next.round", newView.Round, "next.seq", newView.Sequence, "next.proposer", c.valSet.GetProposer(), "next.valSet", c.valSet.List(), "next.size", c.valSet.Size(), "next.IsProposer", c.IsProposer())
}

func newRoundChangeSet(valSet wbft.ValidatorSet) *roundChangeSet {
	return &roundChangeSet{
		validatorSet:         valSet,
		roundChanges:         make(map[uint64]*wbftMsgSet),
		prepareMessages:      make(map[uint64][]*wbfmessage.Prepare),
		highestPreparedRound: make(map[uint64]*big.Int),
		highestPreparedBlock: make(map[uint64]wbft.Proposal),
		mu:                   new(sync.Mutex),
	}
}

// Start implements core.Engine.Start
func (c *Core) Start() error {
	c.logger.Info("WBFT: start")
	// Tests will handle events itself, so we have to make subscribeEvents()
	// be able to call in test.
	c.subscribeEvents()
	c.handlerWg.Add(1)
	go c.handleEvents()

	// Start a new round from last sequence + 1
	c.startNewRound(common.Big0)

	return nil
}

// updateRoundState updates round state by checking if locking block is necessary
func (c *Core) updateRoundState(nextValSet wbft.ValidatorSet, view *wbft.View, roundChange bool) {
	if roundChange && c.current != nil {
		if c.current.preparedBlock != nil && c.backend.HasBadProposal(c.current.preparedBlock.Hash()) {
			c.currentLogger(false, nil).Warn("WBFT: Discarding prepared block due to bad proposal", "hash", c.current.preparedBlock.Hash())
			// clear prepared round and block if we have a bad proposal
			c.current.preparedRound = nil
			c.current.preparedBlock = nil
			// clear prepare and commit seals for the current sequence
			c.ClearExtraSeals(new(big.Int).Add(c.current.sequence, common.Big1))
		}
		c.current = newRoundState(view, nextValSet, c.current.Preprepare, c.current.preparedRound, c.current.preparedBlock, c.current.pendingRequest, c.backend.HasBadProposal)
	} else {
		if c.current != nil {
			// priorState is only set for finalCommitted block
			c.updatePriorState()
		}
		c.current = newRoundState(view, nextValSet, nil, nil, nil, nil, c.backend.HasBadProposal)
	}
	c.valSet = nextValSet
}

func (s *roundState) SetRound(r *big.Int) {
	s.mu.Lock()
	defer s.mu.Unlock()

	s.round = new(big.Int).Set(r)
}

func newWBFTMsgSet(valSet wbft.ValidatorSet) *wbftMsgSet {
	return &wbftMsgSet{
		view: &wbft.View{
			Round:    new(big.Int),
			Sequence: new(big.Int),
		},
		messagesMu: new(sync.Mutex),
		messages:   make(map[common.Address]wbfmessage.WBFTMessage),
		valSet:     valSet,
	}
}

func (c *Core) processBacklog() {
	c.backlogsMu.Lock()
	defer c.backlogsMu.Unlock()

	for srcAddress, backlog := range c.backlogs {
		if backlog == nil {
			continue
		}
		_, src := c.valSet.GetByAddress(srcAddress)
		if src == nil {
			// validator is not available
			delete(c.backlogs, srcAddress)
			continue
		}
		logger := c.logger.New("from", src, "state", c.state)
		isFuture := false

		logger.Trace("WBFT: process backlog")

		// We stop processing if
		//   1. backlog is empty
		//   2. The first message in queue is a future message
		for !(backlog.Empty() || isFuture) {
			msg, prio := backlog.Pop()

			var code uint64
			var view wbft.View
			var event backlogEvent

			code = msg.Code()
			view = msg.View()
			event.msg = msg

			// Push back if it's a future message
			err := c.checkMessage(code, &view)
			if err != nil && err != errExtraSealMessage {
				if err == errFutureMessage {
					// this is still a future message
					logger.Trace("WBFT: stop processing backlog", "msg", msg)
					backlog.Push(msg, prio)
					isFuture = true
					break
				}
				logger.Trace("WBFT: skip backlog message", "msg", msg, "err", err)
				continue
			}
			logger.Trace("WBFT: post backlog event", "msg", msg)

			event.src = src
			go c.sendEvent(event)
		}
	}
}

type backlogEvent struct {
	src wbft.Validator
	msg wbfmessage.WBFTMessage
}

